import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Discipline {
  Refractive = "Cirugía Refractiva",
  Cornea = "Transplante de Córnea",
  Pediatric = "Pediátrica",
  General = "Oftalmología General",
  LowVision = "Baja Visión",
  Oculoplasty = "Oculoplastia",
  Cataract = "Catarata",
  Neuro = "Neuroftalmología",
  DryEye = "Ojo Seco"
}

export enum PatientStatus {
  New = "Nuevo",
  InEvaluation = "En Evaluación",
  PreOp = "Pre-Operatorio",
  Scheduled = "Agendado",
  PostOp = "Post-Operatorio",
  Discharged = "De Alta"
}

export interface Patient {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  dob: string;
  discipline: Discipline;
  status: PatientStatus;
  lastVisit: string;
  balance: number;
  avatarUrl: string;
}

export interface Transaction {
  id: string;
  date: string;
  description: string;
  amount: number;
  type: 'income' | 'expense';
  category: string;
  discipline?: Discipline;
}

export interface KPI {
  label: string;
  value: string | number;
  change: number; // percentage
  trend: 'up' | 'down' | 'neutral';
}

export type ViewState = 'dashboard' | 'crm' | 'refractive-flow' | 'accounting' | 'settings';

import React from 'react';
import { LayoutDashboard, Users, Activity, DollarSign, Settings, LogOut } from 'lucide-react';
import { ViewState } from '../types';
import { LOGO_URL } from '../constants';

interface SidebarProps {
  currentView: ViewState;
  onChangeView: (view: ViewState) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ currentView, onChangeView }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'crm', label: 'Pacientes (CRM)', icon: Users },
    { id: 'refractive-flow', label: 'Flujo Refractiva', icon: Activity },
    { id: 'accounting', label: 'Contabilidad', icon: DollarSign },
  ];

  return (
    <aside className="w-64 bg-slate-900 text-white flex flex-col h-screen shadow-xl z-20">
      <div className="p-6 flex items-center gap-3 border-b border-slate-800">
        <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center p-1 overflow-hidden">
            <img src={LOGO_URL} alt="Centro Laser Logo" className="object-contain w-full h-full" />
        </div>
        <div>
          <h1 className="font-bold text-lg leading-tight">Centro Laser</h1>
          <p className="text-xs text-slate-400">Sistema Integral</p>
        </div>
      </div>

      <nav className="flex-1 py-6 px-3 space-y-1">
        {navItems.map((item) => {
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onChangeView(item.id as ViewState)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg transition-all duration-200 group ${
                isActive 
                  ? 'bg-blue-700 text-white shadow-md' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <item.icon size={20} className={isActive ? 'text-white' : 'text-slate-400 group-hover:text-white'} />
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-800">
        <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:text-red-400 transition-colors rounded-lg hover:bg-slate-800">
          <LogOut size={18} />
          <span className="text-sm font-medium">Cerrar Sesión</span>
        </button>
      </div>
    </aside>
  );
};

import React from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Legend 
} from 'recharts';
import { Users, DollarSign, Activity, Calendar } from 'lucide-react';
import { MOCK_PATIENTS, MOCK_TRANSACTIONS } from '../constants';
import { Discipline } from '../types';

const KPICard: React.FC<{ title: string; value: string; icon: React.ElementType; color: string; trend: string }> = ({ 
  title, value, icon: Icon, color, trend 
}) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
    <div className="flex justify-between items-start">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-900">{value}</h3>
      </div>
      <div className={`p-3 rounded-lg ${color} bg-opacity-10`}>
        <Icon className={`w-6 h-6 ${color.replace('bg-', 'text-')}`} />
      </div>
    </div>
    <div className="mt-4 flex items-center text-sm">
      <span className="text-green-500 font-medium">{trend}</span>
      <span className="text-slate-400 ml-2">vs mes anterior</span>
    </div>
  </div>
);

export const Dashboard: React.FC = () => {
  // Mock calculations
  const totalPatients = MOCK_PATIENTS.length;
  const totalRevenue = MOCK_TRANSACTIONS
    .filter(t => t.type === 'income')
    .reduce((acc, curr) => acc + curr.amount, 0);

  const disciplineData = Object.values(Discipline).map(d => ({
    name: d,
    value: Math.floor(Math.random() * 50) + 10 // Mock data generation
  })).sort((a, b) => b.value - a.value).slice(0, 5); // Top 5

  const COLORS = ['#1e40af', '#3b82f6', '#60a5fa', '#93c5fd', '#bfdbfe'];

  const incomeVsExpenseData = [
    { name: 'Ingresos', value: totalRevenue },
    { name: 'Gastos', value: 207000 }, // Mock expense total
  ];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-900">Panel de Control</h2>
        <div className="text-sm text-slate-500">Última actualización: Hoy, 10:30 AM</div>
      </div>

      {/* KPI Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPICard 
          title="Pacientes Activos" 
          value={totalPatients.toString()} 
          icon={Users} 
          color="bg-blue-600"
          trend="+12%"
        />
        <KPICard 
          title="Ingresos del Mes" 
          value={`RD$ ${(totalRevenue).toLocaleString()}`} 
          icon={DollarSign} 
          color="bg-green-600"
          trend="+8.5%"
        />
        <KPICard 
          title="Cirugías Pendientes" 
          value="18" 
          icon={Activity} 
          color="bg-purple-600"
          trend="-2%"
        />
        <KPICard 
          title="Citas Hoy" 
          value="42" 
          icon={Calendar} 
          color="bg-orange-500"
          trend="+5%"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Patients by Discipline */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Pacientes por Especialidad (Top 5)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={disciplineData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" width={120} tick={{fontSize: 12}} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="value" fill="#1e40af" radius={[0, 4, 4, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Financial Overview */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Balance Financiero</h3>
          <div className="h-80 w-full flex items-center justify-center">
             <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={incomeVsExpenseData}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {incomeVsExpenseData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === 0 ? '#10b981' : '#ef4444'} />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => `RD$ ${value.toLocaleString()}`} />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { REFRACTIVE_STEPS, MOCK_PATIENTS } from '../constants';
import { Patient, Discipline } from '../types';
import { Eye, ChevronRight, MoreHorizontal, Clock } from 'lucide-react';

export const RefractiveFlow: React.FC = () => {
  // Filter only Refractive patients for this view
  const [patients, setPatients] = useState<Patient[]>(
    MOCK_PATIENTS.filter(p => p.discipline === Discipline.Refractive)
  );

  // In a real app, 'status' would map to these steps. 
  // For this demo, we'll randomly assign them to columns if they don't match exactly.
  const getPatientsForStep = (stepId: string) => {
    // Determine pseudo-logic for distribution since our mock data has limited statuses
    // This simulates the organigram flow
    return patients.filter(p => {
        // Simple hashing for demo distribution
        const hash = p.id.charCodeAt(p.id.length - 1) % REFRACTIVE_STEPS.length;
        return REFRACTIVE_STEPS[hash].id === stepId;
    });
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Flujo Cirugía Refractiva</h2>
          <p className="text-slate-500 text-sm mt-1">
            Seguimiento de pacientes basado en el organigrama clínico
          </p>
        </div>
        <button className="bg-blue-900 hover:bg-blue-800 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-sm transition-colors">
          + Nuevo Candidato
        </button>
      </div>

      {/* Kanban Board */}
      <div className="flex-1 overflow-x-auto pb-4">
        <div className="flex gap-4 min-w-max h-full">
          {REFRACTIVE_STEPS.map((step, index) => {
            const stepPatients = getPatientsForStep(step.id);

            return (
              <div key={step.id} className="w-80 flex flex-col h-full">
                {/* Column Header */}
                <div className="flex items-center gap-2 mb-3 bg-slate-200 rounded-t-lg p-3 border-b-4 border-blue-900">
                    <div className="flex items-center justify-center w-6 h-6 rounded-full bg-slate-900 text-white text-xs font-bold">
                        {index + 1}
                    </div>
                  <h3 className="font-semibold text-slate-700 text-sm uppercase tracking-wide">
                    {step.label}
                  </h3>
                  <span className="ml-auto bg-white px-2 py-0.5 rounded-full text-xs text-slate-500 font-bold">
                    {stepPatients.length}
                  </span>
                </div>

                {/* Drop Zone / List */}
                <div className="bg-slate-100 rounded-b-lg p-2 flex-1 overflow-y-auto space-y-3 min-h-[500px]">
                  {stepPatients.length === 0 ? (
                    <div className="h-24 flex items-center justify-center text-slate-400 text-xs italic border-2 border-dashed border-slate-300 rounded-lg">
                      Sin pacientes
                    </div>
                  ) : (
                    stepPatients.map(patient => (
                      <div 
                        key={patient.id} 
                        draggable 
                        className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:shadow-md cursor-grab active:cursor-grabbing transition-all group"
                      >
                        <div className="flex justify-between items-start mb-2">
                          <span className="text-xs font-mono text-slate-400">{patient.id}</span>
                          <button className="text-slate-300 hover:text-slate-600">
                            <MoreHorizontal size={16} />
                          </button>
                        </div>

                        <div className="flex items-center gap-3 mb-3">
                            <img src={patient.avatarUrl} alt="" className="w-10 h-10 rounded-full object-cover border border-slate-100" />
                            <div>
                                <h4 className="text-sm font-bold text-slate-800">{patient.firstName} {patient.lastName}</h4>
                                <span className="text-xs text-slate-500 block">{patient.phone}</span>
                            </div>
                        </div>

                        <div className="flex items-center justify-between pt-3 border-t border-slate-50">
                            <div className="flex items-center gap-1 text-xs text-orange-500 bg-orange-50 px-2 py-1 rounded">
                                <Clock size={12} />
                                <span>15 min</span>
                            </div>
                            <button className="text-blue-600 hover:bg-blue-50 p-1.5 rounded transition-colors">
                                <ChevronRight size={16} />
                            </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { PatientManager } from './components/PatientManager';
import { RefractiveFlow } from './components/RefractiveFlow';
import { Accounting } from './components/Accounting';
import { ViewState } from './types';
import { Bell, HelpCircle, Search } from 'lucide-react';

export default function App() {
  const [currentView, setCurrentView] = useState<ViewState>('dashboard');

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard />;
      case 'crm':
        return <PatientManager />;
      case 'refractive-flow':
        return <RefractiveFlow />;
      case 'accounting':
        return <Accounting />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-slate-50 font-sans">
      <Sidebar currentView={currentView} onChangeView={setCurrentView} />

      <main className="flex-1 flex flex-col min-w-0">
        {/* Top Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10">

          {/* Global Search */}
          <div className="w-96 relative hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Búsqueda global (Pacientes, Citas, Facturas)..." 
              className="w-full bg-slate-100 border-none rounded-lg pl-10 pr-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
            />
          </div>

          <div className="flex items-center gap-4">
            <button className="text-slate-400 hover:text-blue-600 transition-colors relative">
                <Bell size={20} />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full"></span>
            </button>
            <button className="text-slate-400 hover:text-blue-600 transition-colors">
                <HelpCircle size={20} />
            </button>
            <div className="w-px h-8 bg-slate-200 mx-2"></div>
            <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity">
                <div className="text-right hidden sm:block">
                    <p className="text-sm font-bold text-slate-800">Dr. Admin</p>
                    <p className="text-xs text-slate-500">Director Médico</p>
                </div>
                <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold border border-blue-200">
                    DA
                </div>
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-auto p-6 scroll-smooth">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
}

