import React, { useState } from 'react';
import { SERVICES } from '../constants';
import { Discipline } from '../types';
import { Search, Clock, Tag, Stethoscope } from 'lucide-react';

export const ServiceCatalog: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedDiscipline, setSelectedDiscipline] = useState<string>('All');

  const filteredServices = SERVICES.filter(service => {
    const matchesSearch = service.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDiscipline = selectedDiscipline === 'All' || service.discipline === selectedDiscipline;
    return matchesSearch && matchesDiscipline;
  });

  const disciplines = ['All', ...Object.values(Discipline)];

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-900">Catálogo de Servicios</h2>
            <p className="text-slate-500 text-sm">Gestión de procedimientos, costos y duraciones.</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar servicio..." 
              className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Categories / Tags */}
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {disciplines.map(d => (
            <button
                key={d}
                onClick={() => setSelectedDiscipline(d)}
                className={`whitespace-nowrap px-4 py-2 rounded-full text-xs font-semibold transition-colors ${
                    selectedDiscipline === d 
                    ? 'bg-blue-600 text-white shadow-md' 
                    : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                }`}
            >
                {d === 'All' ? 'Todos' : d}
            </button>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 overflow-y-auto pb-4">
        {filteredServices.map(service => (
            <div key={service.id} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 hover:shadow-md transition-shadow flex flex-col">
                <div className="flex justify-between items-start mb-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                        <Stethoscope size={20} />
                    </div>
                    <span className="text-xs font-bold text-slate-400">{service.id}</span>
                </div>
                <h3 className="font-bold text-slate-900 mb-2 leading-tight">{service.name}</h3>
                <p className="text-sm text-slate-500 mb-4 flex-1">{service.description}</p>

                <div className="space-y-2 border-t border-slate-100 pt-4 mt-auto">
                    <div className="flex items-center justify-between text-sm">
