import React, { useState } from 'react';
import { Appointment, UserRole } from '../types';
import { Calendar, Clock, MapPin, Search, Filter, MessageCircle, MoreVertical } from 'lucide-react';

interface AppointmentsProps {
  appointments: Appointment[];
}

export const Appointments: React.FC<AppointmentsProps> = ({ appointments }) => {
  const [filterDate, setFilterDate] = useState<string>('');

  const filteredAppointments = appointments.filter(apt => {
      if (!filterDate) return true;
      return apt.date === filterDate;
  }).sort((a, b) => new Date(`${a.date}T${a.time}`).getTime() - new Date(`${b.date}T${b.time}`).getTime());

  const sendReminder = (apt: Appointment) => {
    // In a real app, this would fetch the patient's phone number.
    // For mock, we'll assume a generic number or stored with the appointment if we modified the type further.
    // Assuming generic or retrieved from Patient Context.
