       {isAddingPatient && (
          <div className="absolute inset-0 bg-slate-900/50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                      <h3 className="text-lg font-bold text-slate-900">Registrar Nuevo Paciente</h3>
                      <button onClick={() => setIsAddingPatient(false)} className="text-slate-400 hover:text-red-500">
                        ✕
                      </button>
                  </div>
                  <div className="p-6 grid grid-cols-2 gap-4">
                      {/* Avatar Upload */}
                      <div className="col-span-2 flex items-center gap-4 mb-2">
                          <div 
                            className="w-16 h-16 rounded-full bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden cursor-pointer hover:bg-slate-200"
                            onClick={() => fileInputRef.current?.click()}
                          >
                             {newPatientAvatar ? (
                                 <img src={newPatientAvatar} alt="Preview" className="w-full h-full object-cover" />
                             ) : (
                                 <Upload size={20} className="text-slate-400" />
                             )}
                          </div>
                          <div>
                              <p className="text-sm font-bold text-slate-700">Foto de Perfil</p>
                              <p className="text-xs text-slate-500">Click para subir imagen</p>
                              <input 
                                ref={fileInputRef}
                                type="file" 
                                accept="image/*" 
                                className="hidden" 
                                onChange={handleAvatarUpload}
                              />
                          </div>
                      </div>

                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Nombre</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="Nombre" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Apellido</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="Apellido" />
                      </div>
                       <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Cédula / ID</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="000-0000000-0" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Teléfono</label>
                          <input type="tel" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="(809) ..." />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Email</label>
                          <input type="email" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="correo@ejemplo.com" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Fecha Nacimiento</label>
                          <input type="date" className="w-full border border-slate-300 rounded p-2 text-sm" />
                      </div>
                       <div className="col-span-2 space-y-1">
                          <label className="text-xs font-bold text-slate-500">Especialidad Inicial</label>
                          <select className="w-full border border-slate-300 rounded p-2 text-sm">
                            {Object.values(Discipline).map(d => <option key={d}>{d}</option>)}
                          </select>
                      </div>
                      <div className="col-span-2 pt-4 border-t border-slate-100 flex justify-end gap-3">
                          <button onClick={() => setIsAddingPatient(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">Cancelar</button>
                          <button onClick={() => setIsAddingPatient(false)} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium">Guardar Paciente</button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Search, Filter, Plus, Phone, Mail, ArrowLeft, Calendar, MessageCircle, Upload, X, ChevronUp, ChevronDown, CheckCircle } from 'lucide-react';
import { Patient, PatientStatus, Discipline, Appointment, CommunicationLog } from '../types';
import { DOCTORS } from '../constants';

interface PatientManagerProps {
  patients: Patient[];
  appointments: Appointment[];
  onAddAppointment: (appointment: Appointment) => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
}

type SortKey = 'lastName' | 'lastInteraction' | 'balance';
type SortDirection = 'asc' | 'desc';

export const PatientManager: React.FC<PatientManagerProps> = ({ patients, appointments, onAddAppointment, onUpdatePatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [isAddingPatient, setIsAddingPatient] = useState(false);
  const [showFilters, setShowFilters] = useState(false);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>(null);

  // New Patient Form State
  const [newPatientAvatar, setNewPatientAvatar] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filter States
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterMinBalance, setFilterMinBalance] = useState<string>('');
  const [filterMaxBalance, setFilterMaxBalance] = useState<string>('');
  const [filterLastCommFrom, setFilterLastCommFrom] = useState<string>('');
  const [filterLastCommTo, setFilterLastCommTo] = useState<string>('');

  // New Appointment Modal State
  const [showApptModal, setShowApptModal] = useState(false);
  const [appointmentSuccess, setAppointmentSuccess] = useState<{show: boolean, details?: Appointment} | null>(null);

  // Communication Log State
  const [activeTab, setActiveTab] = useState<'info'|'history'|'comms'>('info');
  const [newCommNote, setNewCommNote] = useState('');
  const [newCommType, setNewCommType] = useState<CommunicationLog['type']>('Call');

  // Helper to get raw date string for logic
  const getLastCommunicationRaw = (p: Patient): string | null => {
      if (!p.communicationLogs || p.communicationLogs.length === 0) return null;
      const sorted = [...p.communicationLogs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      return sorted[0].date;
  };

  const getLastCommunicationDateDisplay = (p: Patient) => {
      const date = getLastCommunicationRaw(p);
      return date || 'N/A';
  };

  // 1. Filtering Logic
  let processedPatients = patients.filter(p => {
    const term = searchTerm.toLowerCase();
    const cleanTerm = term.replace(/\D/g, ''); // For phone matching (digits only)
    const patientPhoneClean = p.phone.replace(/\D/g, '');

    // Search: Name, ID, Cedula, DOB, Status, Phone, Email
    const matchesSearch = 
        p.firstName.toLowerCase().includes(term) || 
        p.lastName.toLowerCase().includes(term) ||
        p.id.toLowerCase().includes(term) ||
        (p.cedula && p.cedula.includes(term)) || 
        p.dob.includes(term) || 
        p.status.toLowerCase().includes(term) ||
        p.phone.includes(term) ||
        (cleanTerm.length > 0 && patientPhoneClean.includes(cleanTerm)) || // Fuzzy phone match
        p.email.toLowerCase().includes(term);

    const matchesStatus = filterStatus === 'All' || p.status === filterStatus;
    const matchesMinBal = filterMinBalance === '' || p.balance >= Number(filterMinBalance);
    const matchesMaxBal = filterMaxBalance === '' || p.balance <= Number(filterMaxBalance);

    // Date Range Filter for Last Communication
    let matchesDateRange = true;
    if (filterLastCommFrom || filterLastCommTo) {
        const lastComm = getLastCommunicationRaw(p);
        if (!lastComm) {
            matchesDateRange = false; // If filtering by date and no comms, exclude
        } else {
            const commDate = new Date(lastComm).getTime();
            const fromDate = filterLastCommFrom ? new Date(filterLastCommFrom).getTime() : -Infinity;
            const toDate = filterLastCommTo ? new Date(filterLastCommTo).getTime() : Infinity;
            matchesDateRange = commDate >= fromDate && commDate <= toDate;
        }
    }

    return matchesSearch && matchesStatus && matchesMinBal && matchesMaxBal && matchesDateRange;
  });

  // 2. Sorting Logic
  if (sortConfig !== null) {
      processedPatients.sort((a, b) => {
          let aValue: any = '';
          let bValue: any = '';

          if (sortConfig.key === 'lastName') {
              aValue = a.lastName.toLowerCase();
              bValue = b.lastName.toLowerCase();
          } else if (sortConfig.key === 'balance') {
              aValue = a.balance;
              bValue = b.balance;
          } else if (sortConfig.key === 'lastInteraction') {
              aValue = getLastCommunicationRaw(a) || '';
              bValue = getLastCommunicationRaw(b) || '';
          }

          if (aValue < bValue) {
              return sortConfig.direction === 'asc' ? -1 : 1;
          }
          if (aValue > bValue) {
              return sortConfig.direction === 'asc' ? 1 : -1;
          }
          return 0;
      });
  }

  const handleSort = (key: SortKey) => {
      let direction: SortDirection = 'asc';
      if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
      if (sortConfig?.key !== key) return <div className="w-4 h-4" />; // Placeholder
      return sortConfig.direction === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />;
  };

  const getWhatsAppLink = (phone: string) => {
      const cleanNumber = phone.replace(/\D/g, '');
      const fullNumber = cleanNumber.length === 10 ? `1${cleanNumber}` : cleanNumber;
      return `https://wa.me/${fullNumber}`;
  };

  const handleAddAppointment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (!selectedPatient) return;

    const newAppt: Appointment = {
      id: `APT-${Date.now()}`,
      patientId: selectedPatient.id,
      patientName: `${selectedPatient.firstName} ${selectedPatient.lastName}`,
      date: formData.get('date') as string,
      time: formData.get('time') as string,
      reason: formData.get('reason') as string,
      doctor: formData.get('doctor') as string,
      status: 'Scheduled',
      discipline: selectedPatient.discipline
    };
    onAddAppointment(newAppt);
    setShowApptModal(false);

    // Show Toast Notification
    setAppointmentSuccess({ show: true, details: newAppt });
    setTimeout(() => {
        setAppointmentSuccess(null);
    }, 6000); // Increased slightly to give user time to read
  };

  const handleAddCommLog = () => {
    if (!selectedPatient || !newCommNote) return;
    const newLog: CommunicationLog = {
      id: `CL-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      type: newCommType,
      notes: newCommNote,
      staffName: 'Staff Actual' 
    };
    const updatedPatient = {
      ...selectedPatient,
      communicationLogs: [newLog, ...(selectedPatient.communicationLogs || [])]
    };
    onUpdatePatient(updatedPatient);
    setSelectedPatient(updatedPatient);
    setNewCommNote('');
  };

  const handleAvatarUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (e) => {
              if (e.target?.result) {
                  setNewPatientAvatar(e.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  if (selectedPatient) {
    return (
      <div className="h-full flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
        {/* Detail View Header */}
        <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center gap-4">
          <button 
            onClick={() => setSelectedPatient(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-slate-200 shadow-sm"
          >
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div className="flex items-center gap-4 flex-1">
            <img 
                src={selectedPatient.avatarUrl || 'https://via.placeholder.com/150'} 
                alt="Profile" 
                className="w-16 h-16 rounded-full border-4 border-white shadow-sm object-cover bg-slate-200" 
            />
            <div>
              <h2 className="text-2xl font-bold text-slate-900">{selectedPatient.firstName} {selectedPatient.lastName}</h2>
              <div className="flex items-center gap-3 text-sm text-slate-500">
                <span>{selectedPatient.id}</span>
                {selectedPatient.cedula && (
                    <span className="bg-slate-100 px-2 py-0.5 rounded text-xs font-mono">{selectedPatient.cedula}</span>
                )}
                <span className="text-blue-600 font-medium px-2 py-0.5 bg-blue-50 rounded-full text-xs">{selectedPatient.discipline}</span>
                <span>{selectedPatient.status}</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button 
                onClick={() => setShowApptModal(true)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm"
            >
                <Calendar size={16} /> Agendar Cita
            </button>
            <div className="text-right px-4 py-2 bg-white rounded-lg border border-slate-200">
                <div className="text-xs text-slate-500 uppercase font-bold">Balance</div>
                <div className={`text-lg font-bold ${selectedPatient.balance > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                    RD$ {selectedPatient.balance.toLocaleString()}
                </div>
            </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
            {/* Sidebar Info */}
            <div className="w-80 border-r border-slate-100 p-6 overflow-y-auto space-y-6 bg-white">
                 <div>
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3">Contacto Rápido</h3>
                    <div className="space-y-3">
                        <div className="flex items-center gap-3 text-slate-700 p-2 bg-slate-50 rounded-lg">
                            <Phone size={18} />
                            <span className="font-mono text-sm">{selectedPatient.phone}</span>
                            <a 
                                href={getWhatsAppLink(selectedPatient.phone)} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="ml-auto bg-green-500 hover:bg-green-600 text-white px-[6px] py-[3px] rounded-md shadow-sm transition-colors border border-green-600 flex items-center gap-1"
                                title="Abrir WhatsApp"
                            >
                                <MessageCircle size={14} />
                            </a>
                        </div>
                        <div className="flex items-center gap-3 text-slate-700 p-2 bg-slate-50 rounded-lg">
                            <Mail size={18} />
                            <span className="text-sm truncate">{selectedPatient.email}</span>
                        </div>
                    </div>
                </div>
                 <div>
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3">Seguro Médico</h3>
                    <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                        <p className="font-bold text-blue-900 text-sm">{selectedPatient.insuranceProvider || 'Privado'}</p>
                        <p className="font-mono text-slate-600 text-xs mt-1">{selectedPatient.policyNumber || 'N/A'}</p>
                    </div>
                </div>
            </div>

            {/* Main Tabs */}
            <div className="flex-1 flex flex-col bg-slate-50">
                <div className="flex border-b border-slate-200 bg-white px-6">
                    <button 
                        onClick={() => setActiveTab('info')}
                        className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'info' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                    >
                        Información General
                    </button>
                    <button 
                         onClick={() => setActiveTab('history')}
                        className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'history' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                    >
                        Historial Médico
                    </button>
                    <button 
                         onClick={() => setActiveTab('comms')}
                        className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'comms' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                    >
                        Bitácora Comunicación
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6">
                    {/* INFO TAB */}
                    {activeTab === 'info' && (
                        <div className="space-y-6">
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                                <h3 className="font-bold text-slate-900 mb-4">Notas Clínicas</h3>
                                <p className="text-slate-600 text-sm leading-relaxed">{selectedPatient.notes || 'No hay notas registradas.'}</p>
                            </div>
                        </div>
                    )}

                    {/* HISTORY TAB */}
                    {activeTab === 'history' && (
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                            <div className="relative border-l-2 border-slate-200 ml-3 space-y-8 pl-8 py-2">
                                {selectedPatient.medicalHistory.map((record) => (
                                    <div key={record.id} className="relative">
                                        <span className="absolute -left-[41px] top-1 w-5 h-5 rounded-full bg-blue-600 border-4 border-white shadow-sm"></span>
                                        <div className="flex justify-between items-start mb-1">
                                            <h4 className="font-bold text-slate-800">{record.title}</h4>
                                            <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded">{record.date}</span>
                                        </div>
                                        <span className="text-xs font-bold text-blue-600 uppercase mb-2 block">{record.type}</span>
                                        <p className="text-slate-600 text-sm leading-relaxed mb-2">{record.notes}</p>
                                        <p className="text-xs text-slate-400 italic">{record.doctor}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* COMMS TAB */}
                    {activeTab === 'comms' && (
                        <div className="space-y-4">
                             <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                                <h4 className="text-sm font-bold text-slate-900 mb-2">Registrar Interacción</h4>
                                <div className="flex gap-2 mb-2">
                                    {['Call', 'WhatsApp', 'Email', 'In-Person'].map((type) => (
                                        <button 
                                            key={type}
                                            onClick={() => setNewCommType(type as any)}
                                            className={`px-3 py-1 rounded-full text-xs font-medium border ${newCommType === type ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-600 border-slate-200'}`}
                                        >
                                            {type}
                                        </button>
                                    ))}
                                </div>
                                <textarea 
                                    className="w-full border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                    placeholder="Escribe los detalles de la comunicación..."
                                    rows={2}
                                    value={newCommNote}
                                    onChange={(e) => setNewCommNote(e.target.value)}
                                ></textarea>
                                <div className="text-right mt-2">
                                    <button onClick={handleAddCommLog} className="bg-slate-900 text-white text-xs font-bold px-4 py-2 rounded-lg hover:bg-slate-800">Guardar Nota</button>
                                </div>
                             </div>

                             <div className="space-y-2">
                                {selectedPatient.communicationLogs?.map((log) => (
                                    <div key={log.id} className="bg-white p-4 rounded-xl border border-slate-200 flex gap-4">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${
                                            log.type === 'WhatsApp' ? 'bg-green-100 text-green-600' : 
                                            log.type === 'Email' ? 'bg-purple-100 text-purple-600' : 'bg-blue-100 text-blue-600'
                                        }`}>
                                            {log.type === 'WhatsApp' ? <MessageCircle size={18}/> : log.type === 'Email' ? <Mail size={18}/> : <Phone size={18}/>}
                                        </div>
                                        <div className="flex-1">
                                            <div className="flex justify-between items-start">
                                                <h5 className="text-sm font-bold text-slate-900">{log.type}</h5>
                                                <span className="text-xs text-slate-400">{log.date}</span>
                                            </div>
                                            <p className="text-sm text-slate-600 mt-1">{log.notes}</p>
                                            <p className="text-xs text-slate-400 mt-2">Registrado por: {log.staffName}</p>
                                        </div>
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* Schedule Modal */}
        {showApptModal && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
                <div className="bg-white rounded-xl shadow-2xl w-full max-w-md animate-in zoom-in duration-200">
                    <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                        <h3 className="font-bold text-slate-900">Agendar Cita</h3>
                        <button onClick={() => setShowApptModal(false)}><X size={20} className="text-slate-400" /></button>
                    </div>
                    <form onSubmit={handleAddAppointment} className="p-6 space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-1">Fecha</label>
                                <input type="date" name="date" required className="w-full border border-slate-300 rounded p-2 text-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-1">Hora</label>
                                <input type="time" name="time" required className="w-full border border-slate-300 rounded p-2 text-sm" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Doctor</label>
                            <select name="doctor" className="w-full border border-slate-300 rounded p-2 text-sm">
                                {DOCTORS.map(doc => <option key={doc} value={doc}>{doc}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Motivo / Procedimiento</label>
                            <input type="text" name="reason" required placeholder="Ej: Consulta General" className="w-full border border-slate-300 rounded p-2 text-sm" />
                        </div>
                        <div className="pt-2">
                            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 rounded-lg text-sm">Confirmar Cita</button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* Appointment Success Toast */}
        {appointmentSuccess && appointmentSuccess.details && (
            <div className="absolute bottom-6 right-6 z-[60] animate-in slide-in-from-bottom-5 duration-300">
                <div className="bg-slate-900 text-white p-4 rounded-xl shadow-2xl border border-slate-700 flex gap-4 max-w-md">
                    <div className="text-green-400 mt-1">
                        <CheckCircle size={24} />
                    </div>
                    <div>
                        <h4 className="font-bold text-lg mb-1">¡Cita Agendada!</h4>
                        <div className="text-sm text-slate-300 space-y-1">
                            <p><span className="text-slate-500 uppercase text-xs font-bold mr-2">Paciente:</span> {appointmentSuccess.details.patientName}</p>
                            <p><span className="text-slate-500 uppercase text-xs font-bold mr-2">Fecha:</span> {appointmentSuccess.details.date} a las {appointmentSuccess.details.time}</p>
                            <p><span className="text-slate-500 uppercase text-xs font-bold mr-2">Doctor:</span> {appointmentSuccess.details.doctor}</p>
                        </div>
                    </div>
                    <button 
                        onClick={() => setAppointmentSuccess(null)}
                        className="text-slate-500 hover:text-white h-fit"
                    >
                        <X size={16} />
                    </button>
                </div>
            </div>
        )}
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col relative">
      {/* List Header */}
      <div className="p-6 border-b border-slate-100">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Pacientes (CRM)</h2>
          <button 
            onClick={() => { setIsAddingPatient(true); setNewPatientAvatar(''); }}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-sm"
          >
            <Plus size={18} />
            Registrar Paciente
          </button>
        </div>

        <div className="flex flex-col gap-4">
            <div className="flex gap-4">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                    <input 
                    type="text" 
                    placeholder="Nombre, ID, Cédula, Teléfono..." 
                    className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <button 
                    onClick={() => setShowFilters(!showFilters)}
                    className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-medium text-sm transition-colors ${showFilters ? 'bg-blue-50 border-blue-200 text-blue-700' : 'border-slate-300 text-slate-600 hover:bg-slate-50'}`}
                >
                    <Filter size={18} />
                    Filtros
                </button>
            </div>

            {showFilters && (
                <div className="p-4 bg-slate-50 border border-slate-200 rounded-lg grid grid-cols-1 md:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Estado</label>
                        <select 
                            value={filterStatus}
                            onChange={(e) => setFilterStatus(e.target.value)}
                            className="w-full border border-slate-300 rounded p-2 text-sm bg-white"
                        >
                            <option value="All">Todos</option>
                            {Object.values(PatientStatus).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-slate-500 mb-1">Balance Min</label>
                         <input 
                            type="number" 
                            placeholder="0"
                            value={filterMinBalance}
                            onChange={(e) => setFilterMinBalance(e.target.value)}
                            className="w-full border border-slate-300 rounded p-2 text-sm"
                         />
                    </div>
                     <div>
                         <label className="block text-xs font-bold text-slate-500 mb-1">Balance Max</label>
                         <input 
                            type="number" 
                            placeholder="Max"
                            value={filterMaxBalance}
                            onChange={(e) => setFilterMaxBalance(e.target.value)}
                            className="w-full border border-slate-300 rounded p-2 text-sm"
                         />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Última Comunicación</label>
                        <div className="flex gap-2">
                            <input 
                                type="date" 
                                value={filterLastCommFrom}
                                onChange={(e) => setFilterLastCommFrom(e.target.value)}
                                className="w-full border border-slate-300 rounded p-2 text-xs"
                                placeholder="Desde"
                            />
                            <input 
                                type="date" 
                                value={filterLastCommTo}
                                onChange={(e) => setFilterLastCommTo(e.target.value)}
                                className="w-full border border-slate-300 rounded p-2 text-xs"
                                placeholder="Hasta"
                            />
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* Patient List */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50 sticky top-0 z-10">
            <tr>
              <th 
                className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider cursor-pointer hover:bg-slate-100 hover:text-blue-600 transition-colors group"
                onClick={() => handleSort('lastName')}
              >
                <div className="flex items-center gap-1">
                    Paciente {getSortIcon('lastName')}
                </div>
              </th>
              <th className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider">Especialidad</th>
              <th className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider">Estado</th>
              <th 
                className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider cursor-pointer hover:bg-slate-100 hover:text-blue-600 transition-colors group"
                onClick={() => handleSort('lastInteraction')}
              >
                 <div className="flex items-center gap-1">
                    Últ. Interacción {getSortIcon('lastInteraction')}
                 </div>
              </th>
              <th className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider">Contacto</th>
              <th 
                className="px-6 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wider cursor-pointer hover:bg-slate-100 hover:text-blue-600 transition-colors group"
                onClick={() => handleSort('balance')}
              >
                 <div className="flex items-center gap-1">
                    Balance {getSortIcon('balance')}
                 </div>
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {processedPatients.map((patient) => (
              <tr 
                key={patient.id} 
                onClick={() => setSelectedPatient(patient)}
                className="hover:bg-blue-50 transition-colors group cursor-pointer"
              >
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center gap-3">
                    <img src={patient.avatarUrl || 'https://via.placeholder.com/150'} alt="" className="w-10 h-10 rounded-full object-cover bg-slate-200" />
                    <div>
                      <div className="font-medium text-slate-900 group-hover:text-blue-700">{patient.firstName} {patient.lastName}</div>
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-slate-500">{patient.id}</span>
                        {patient.cedula && (
                            <span className="text-[10px] text-slate-400 font-mono bg-slate-100 px-1 rounded">{patient.cedula}</span>
                        )}
                      </div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-700">
                    {patient.discipline}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`text-sm ${
                    patient.status === PatientStatus.Scheduled ? 'text-green-600 font-medium' : 
                    patient.status === PatientStatus.PreOp ? 'text-orange-600 font-medium' : 'text-slate-600'
                  }`}>
                    {patient.status}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">
                    {getLastCommunicationDateDisplay(patient)}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center gap-3 text-slate-400" onClick={(e) => e.stopPropagation()}>
                    <button className="hover:text-blue-600" title={patient.phone}><Phone size={16} /></button>
                    <a 
                        href={getWhatsAppLink(patient.phone)} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="bg-green-500 hover:bg-green-600 text-white px-[6px] py-[3px] rounded-md shadow-md transition-all flex items-center gap-1 text-xs font-bold"
                        title="Chat en WhatsApp"
                    >
                        <MessageCircle size={14} /> WhatsApp
                    </a>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className={`text-sm font-medium ${patient.balance > 0 ? 'text-red-600' : 'text-slate-900'}`}>
                    RD$ {patient.balance.toLocaleString()}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

       {/* Add Patient Modal */}
       {isAddingPatient && (
          <div className="absolute inset-0 bg-slate-900/50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                      <h3 className="text-lg font-bold text-slate-900">Registrar Nuevo Paciente</h3>
                      <button onClick={() => setIsAddingPatient(false)} className="text-slate-400 hover:text-red-500">
                        ✕
                      </button>
                  </div>
                  <div className="p-6 grid grid-cols-2 gap-4">
                      {/* Avatar Upload */}
                      <div className="col-span-2 flex items-center gap-4 mb-2">
                          <div 
                            className="w-16 h-16 rounded-full bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden cursor-pointer hover:bg-slate-200"
                            onClick={() => fileInputRef.current?.click()}
                          >
                             {newPatientAvatar ? (
                                 <img src={newPatientAvatar} alt="Preview" className="w-full h-full object-cover" />
                             ) : (
                                 <Upload size={20} className="text-slate-400" />
                             )}
                          </div>
                          <div>
                              <p className="text-sm font-bold text-slate-700">Foto de Perfil</p>
                              <p className="text-xs text-slate-500">Click para subir imagen</p>
                              <input 
                                ref={fileInputRef}
                                type="file" 
                                accept="image/*" 
                                className="hidden" 
                                onChange={handleAvatarUpload}
                              />
                          </div>
                      </div>

                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Nombre</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="Nombre" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Apellido</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="Apellido" />
                      </div>
                       <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Cédula / ID</label>
                          <input type="text" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="000-0000000-0" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Teléfono</label>
                          <input type="tel" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="(809) ..." />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Email</label>
                          <input type="email" className="w-full border border-slate-300 rounded p-2 text-sm" placeholder="correo@ejemplo.com" />
                      </div>
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500">Fecha Nacimiento</label>
                          <input type="date" className="w-full border border-slate-300 rounded p-2 text-sm" />
                      </div>
                       <div className="col-span-2 space-y-1">
                          <label className="text-xs font-bold text-slate-500">Especialidad Inicial</label>
                          <select className="w-full border border-slate-300 rounded p-2 text-sm">
                            {Object.values(Discipline).map(d => <option key={d}>{d}</option>)}
                          </select>
                      </div>
                      <div className="col-span-2 pt-4 border-t border-slate-100 flex justify-end gap-3">
                          <button onClick={() => setIsAddingPatient(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">Cancelar</button>
                          <button onClick={() => setIsAddingPatient(false)} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium">Guardar Paciente</button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export enum Discipline {
  Refractive = "Cirugía Refractiva",
  Cornea = "Transplante de Córnea",
  Pediatric = "Pediátrica",
  General = "Oftalmología General",
  LowVision = "Baja Visión",
  Oculoplasty = "Oculoplastia",
  Cataract = "Catarata",
  Neuro = "Neuroftalmología",
  DryEye = "Ojo Seco"
}

export enum PatientStatus {
  New = "Nuevo",
  InEvaluation = "En Evaluación",
  PreOp = "Pre-Operatorio",
  Scheduled = "Agendado",
  PostOp = "Post-Operatorio",
  Discharged = "De Alta"
}

export interface MedicalRecord {
  id: string;
  date: string;
  type: 'Consulta' | 'Cirugía' | 'Seguimiento';
  title: string;
  notes: string;
  doctor: string;
}

export interface LabResult {
  id: string;
  date: string;
  testName: string;
  result: string;
  referenceRange: string;
  status: 'Normal' | 'Abnormal' | 'Critical';
  fileUrl?: string;
}

export interface Examination {
  id: string;
  date: string;
  examType: string; // e.g., "Pentacam", "OCT", "Topography"
  summary: string;
  performedBy: string;
  imageUrl?: string;
}

export interface ProcedureLog {
  id: string;
  date: string;
  procedureName: string;
  doctor: string;
  outcome: string;
  notes: string;
}

export interface CommunicationLog {
  id: string;
  date: string;
  type: 'Call' | 'Email' | 'WhatsApp' | 'In-Person';
  notes: string;
  staffName: string;
}

export interface Patient {
  id: string;
  cedula?: string; 
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  dob: string;
  discipline: Discipline;
  status: PatientStatus;
  lastVisit: string;
  balance: number;
  avatarUrl: string;
  insuranceProvider?: string;
  policyNumber?: string;
  medicalHistory: MedicalRecord[];
  communicationLogs: CommunicationLog[];
  labResults: LabResult[];
  examinations: Examination[];
  procedures: ProcedureLog[];
  notes?: string;
}

export interface Appointment {
  id: string;
  patientId: string;
  patientName: string;
  date: string;
  time: string;
  reason: string;
  doctor: string;
  status: 'Scheduled' | 'Completed' | 'Cancelled';
  discipline: Discipline;
}

export interface Service {
  id: string;
  name: string;
  description: string;
  discipline: Discipline;
  durationMinutes: number;
  cost: number;
}

export interface Transaction {
  id: string;
  date: string;
  description: string;
  amount: number;
  type: 'income' | 'expense';
  category: string;
  discipline?: Discipline;
  patientId?: string; 
}

export interface KPI {
  label: string;
  value: string | number;
  change: number; 
  trend: 'up' | 'down' | 'neutral';
}

export type UserRole = 'admin' | 'doctor' | 'patient';

export type ViewState = 'dashboard' | 'crm' | 'appointments' | 'refractive-flow' | 'accounting' | 'services' | 'settings';

import React, { useState, useRef } from 'react';
import { Search, Filter, Plus, Phone, Mail, ArrowLeft, Calendar, MessageCircle, Upload, X, ChevronUp, ChevronDown, CheckCircle, FileText, Microscope, Clipboard, Activity } from 'lucide-react';
import { Patient, PatientStatus, Discipline, Appointment, CommunicationLog } from '../types';
import { DOCTORS } from '../constants';

interface PatientManagerProps {
  patients: Patient[];
  appointments: Appointment[];
  onAddAppointment: (appointment: Appointment) => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
}

type SortKey = 'lastName' | 'lastInteraction' | 'balance';
type SortDirection = 'asc' | 'desc';

export const PatientManager: React.FC<PatientManagerProps> = ({ patients, appointments, onAddAppointment, onUpdatePatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [isAddingPatient, setIsAddingPatient] = useState(false);
  const [showFilters, setShowFilters] = useState(false);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>(null);

  // New Patient Form State
  const [newPatientAvatar, setNewPatientAvatar] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filter States
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterMinBalance, setFilterMinBalance] = useState<string>('');
  const [filterMaxBalance, setFilterMaxBalance] = useState<string>('');
  const [filterLastCommFrom, setFilterLastCommFrom] = useState<string>('');
  const [filterLastCommTo, setFilterLastCommTo] = useState<string>('');

  // New Appointment Modal State
  const [showApptModal, setShowApptModal] = useState(false);
  const [appointmentSuccess, setAppointmentSuccess] = useState<{show: boolean, details?: Appointment} | null>(null);

  // Tab State
  const [activeTab, setActiveTab] = useState<'info'|'history'|'comms'|'labs'|'exams'|'procedures'>('info');
  const [newCommNote, setNewCommNote] = useState('');
  const [newCommType, setNewCommType] = useState<CommunicationLog['type']>('Call');

  // Helper to get raw date string for logic
  const getLastCommunicationRaw = (p: Patient): string | null => {
      if (!p.communicationLogs || p.communicationLogs.length === 0) return null;
      const sorted = [...p.communicationLogs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      return sorted[0].date;
  };

  const getLastCommunicationDateDisplay = (p: Patient) => {
      const date = getLastCommunicationRaw(p);
      return date || 'N/A';
  };

  // 1. Filtering Logic
  let processedPatients = patients.filter(p => {
    const term = searchTerm.toLowerCase();
    const cleanTerm = term.replace(/\D/g, ''); // For phone matching (digits only)
    const patientPhoneClean = p.phone.replace(/\D/g, '');

    // Search: Name, ID, Cedula, DOB, Status, Phone, Email
    const matchesSearch = 
        p.firstName.toLowerCase().includes(term) || 
        p.lastName.toLowerCase().includes(term) ||
        p.id.toLowerCase().includes(term) ||
        (p.cedula && p.cedula.includes(term)) || 
        p.dob.includes(term) || 
        p.status.toLowerCase().includes(term) ||
        p.phone.includes(term) ||
        (cleanTerm.length > 0 && patientPhoneClean.includes(cleanTerm)) || // Fuzzy phone match
        p.email.toLowerCase().includes(term);

    const matchesStatus = filterStatus === 'All' || p.status === filterStatus;
    const matchesMinBal = filterMinBalance === '' || p.balance >= Number(filterMinBalance);
    const matchesMaxBal = filterMaxBalance === '' || p.balance <= Number(filterMaxBalance);

    // Date Range Filter for Last Communication
    let matchesDateRange = true;
    if (filterLastCommFrom || filterLastCommTo) {
        const lastComm = getLastCommunicationRaw(p);
        if (!lastComm) {
            matchesDateRange = false; // If filtering by date and no comms, exclude
        } else {
            const commDate = new Date(lastComm).getTime();
            const fromDate = filterLastCommFrom ? new Date(filterLastCommFrom).getTime() : -Infinity;
            const toDate = filterLastCommTo ? new Date(filterLastCommTo).getTime() : Infinity;
            matchesDateRange = commDate >= fromDate && commDate <= toDate;
        }
    }

    return matchesSearch && matchesStatus && matchesMinBal && matchesMaxBal && matchesDateRange;
  });

  // 2. Sorting Logic
  if (sortConfig !== null) {
      processedPatients.sort((a, b) => {
          let aValue: any = '';
          let bValue: any = '';

          if (sortConfig.key === 'lastName') {
              aValue = a.lastName.toLowerCase();
              bValue = b.lastName.toLowerCase();
          } else if (sortConfig.key === 'balance') {
              aValue = a.balance;
              bValue = b.balance;
          } else if (sortConfig.key === 'lastInteraction') {
              aValue = getLastCommunicationRaw(a) || '';
              bValue = getLastCommunicationRaw(b) || '';
          }

          if (aValue < bValue) {
              return sortConfig.direction === 'asc' ? -1 : 1;
          }
          if (aValue > bValue) {
              return sortConfig.direction === 'asc' ? 1 : -1;
          }
          return 0;
      });
  }

  const handleSort = (key: SortKey) => {
      let direction: SortDirection = 'asc';
      if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
      if (sortConfig?.key !== key) return <div className="w-4 h-4" />; // Placeholder
      return sortConfig.direction === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />;
  };

  const getWhatsAppLink = (phone: string) => {
      const cleanNumber = phone.replace(/\D/g, '');
      const fullNumber = cleanNumber.length === 10 ? `1${cleanNumber}` : cleanNumber;
      return `https://wa.me/${fullNumber}`;
  };

  const handleAddAppointment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (!selectedPatient) return;

    const newAppt: Appointment = {
      id: `APT-${Date.now()}`,
      patientId: selectedPatient.id,
      patientName: `${selectedPatient.firstName} ${selectedPatient.lastName}`,
      date: formData.get('date') as string,
      time: formData.get('time') as string,
      reason: formData.get('reason') as string,
      doctor: formData.get('doctor') as string,
      status: 'Scheduled',
      discipline: selectedPatient.discipline
    };
    onAddAppointment(newAppt);
    setShowApptModal(false);

    // Show Toast Notification
    setAppointmentSuccess({ show: true, details: newAppt });
    setTimeout(() => {
        setAppointmentSuccess(null);
    }, 6000); // Increased slightly to give user time to read
  };

  const handleAddCommLog = () => {
    if (!selectedPatient || !newCommNote) return;
    const newLog: CommunicationLog = {
      id: `CL-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      type: newCommType,
      notes: newCommNote,
      staffName: 'Staff Actual' 
    };
    const updatedPatient = {
      ...selectedPatient,
      communicationLogs: [newLog, ...(selectedPatient.communicationLogs || [])]
    };
    onUpdatePatient(updatedPatient);
    setSelectedPatient(updatedPatient);
    setNewCommNote('');
  };

  const handleAvatarUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (e) => {
              if (e.target?.result) {
                  setNewPatientAvatar(e.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  if (selectedPatient) {
    return (
      <div className="h-full flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
        {/* Detail View Header */}
        <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center gap-4">
          <button 
            onClick={() => setSelectedPatient(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-slate-200 shadow-sm"
          >
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div className="flex items-center gap-4 flex-1">
            <img 
                src={selectedPatient.avatarUrl || 'https://via.placeholder.com/150'} 
                alt="Profile" 
                className="w-16 h-16 rounded-full border-4 border-white shadow-sm object-cover bg-slate-200" 
            />
            <div>
              <h2 className="text-2xl font-bold text-slate-900">{selectedPatient.firstName} {selectedPatient.lastName}</h2>
              <div className="flex items-center gap-3 text-sm text-slate-500">
                <span>{selectedPatient.id}</span>
                {selectedPatient.cedula && (
                    <span className="bg-slate-100 px-2 py-0.5 rounded text-xs font-mono">{selectedPatient.cedula}</span>
                )}
                <span className="text-blue-600 font-medium px-2 py-0.5 bg-blue-50 rounded-full text-xs">{selectedPatient.discipline}</span>
                <span>{selectedPatient.status}</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button 
