                    )}

                    {/* AI SCREENING TAB */}
                    {activeTab === 'ai' && (
                        <div className="space-y-6">
                             <div className="bg-indigo-900 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
                                <div className="absolute right-0 top-0 opacity-10 transform translate-x-10 -translate-y-10">
                                    <BrainCircuit size={180} />
                                </div>
                                <div className="relative z-10">
                                    <h3 className="text-lg font-bold mb-2 flex items-center gap-2">
                                        <ScanEye size={24} className="text-indigo-400"/> Screening de Retinopatía Diabética (IA)
                                    </h3>
                                    <p className="text-indigo-200 text-sm max-w-lg mb-4">
                                        Análisis automatizado utilizando algoritmos de aprendizaje profundo para la detección temprana de retinopatía diabética, glaucoma y edema macular.
                                    </p>
                                    <button className="bg-white text-indigo-900 px-4 py-2 rounded-lg font-bold text-sm hover:bg-indigo-50 transition-colors shadow-sm">
