                                        <div key={scan.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6">
                                            <div className="w-full md:w-48 h-48 bg-slate-900 rounded-lg overflow-hidden shrink-0 relative group">
                                                <img src={scan.imageUrl} alt="Retina Scan" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
                                                <div className="absolute inset-0 flex items-center justify-center">
                                                    <ScanEye className="text-white opacity-50" size={32}/>
                                                </div>
                                            </div>
                                            <div className="flex-1">
                                                <div className="flex justify-between items-start mb-2">
                                                    <div>
                                                        <h4 className="font-bold text-slate-900 text-lg">Análisis de {scan.modality}</h4>
