                                                        scan.riskLevel === 'Moderado' ? 'bg-yellow-100 text-yellow-700 border-yellow-200' :
                                                        'bg-red-100 text-red-700 border-red-200'
                                                    }`}>
                                                        Riesgo: {scan.riskLevel}
