                                <div 
                                    className="w-24 h-24 rounded-full bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden cursor-pointer hover:bg-slate-200 shrink-0 transition-colors"
                                    onClick={() => fileInputRef.current?.click()}
                                >
                                    {newPatientAvatar ? (
                                        <img src={newPatientAvatar} alt="Preview" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="text-center p-2">
                                            <Upload size={20} className="text-slate-400 mx-auto mb-1" />
                                            <span className="text-[10px] text-slate-500 block">Subir Foto</span>
                                        </div>
                                    )}
                                </div>
                                <div className="flex-1">
                                    <p className="text-sm text-slate-600 mb-2">Imagen de perfil del paciente.</p>
                                    <input 
                                        ref={fileInputRef}
                                        type="file" 
                                        accept="image/*" 
                                        className="hidden" 
                                        onChange={handleAvatarUpload}
                                    />
                                    <button type="button" onClick={() => fileInputRef.current?.click()} className="text-xs font-bold text-blue-600 hover:underline">
                                        Seleccionar archivo...
                                    </button>
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Nombre <span className="text-red-500">*</span></label>
                                    <input name="firstName" required type="text" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Nombre" />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Apellido <span className="text-red-500">*</span></label>
                                    <input name="lastName" required type="text" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Apellido" />
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Cédula / Pasaporte</label>
                                    <input name="cedula" type="text" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="000-0000000-0" />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Fecha Nacimiento <span className="text-red-500">*</span></label>
                                    <input name="dob" required type="date" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                </div>
                             </div>
                         </div>

                         {/* Right Column: Contact & Clinical */}
                         <div className="space-y-6">
                            {/* Contact */}
                            <div className="space-y-4">
                                <div className="flex items-center gap-2 text-slate-800 font-bold border-b border-slate-100 pb-2">
                                    <Phone size={18} className="text-blue-600"/>
                                    <h4>Información de Contacto</h4>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Teléfono Móvil <span className="text-red-500">*</span></label>
                                    <input name="phone" required type="tel" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="(809) 000-0000" />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-500">Correo Electrónico <span className="text-red-500">*</span></label>
                                    <input 
                                        name="email" 
                                        required 
                                        type="email" 
                                        className={`w-full border rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none ${emailError ? 'border-red-500' : 'border-slate-300'}`} 
                                        placeholder="paciente@ejemplo.com" 
                                        onChange={() => setEmailError('')}
                                    />
                                    {emailError && <p className="text-xs text-red-500 mt-1">{emailError}</p>}
                                </div>
                            </div>

                            {/* Clinical */}
                            <div className="space-y-4">
                                <div className="flex items-center gap-2 text-slate-800 font-bold border-b border-slate-100 pb-2">
                                    <Activity size={18} className="text-blue-600"/>
                                    <h4>Datos Clínicos Iniciales</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1">
                                        <label className="text-xs font-bold text-slate-500">Especialidad de Interés</label>
                                        <select name="discipline" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                                            {Object.values(Discipline).map(d => <option key={d} value={d}>{d}</option>)}
                                        </select>
                                    </div>
                                    <div className="space-y-1">
                                        <label className="text-xs font-bold text-slate-500">Estado Inicial</label>
                                        <select name="status" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={PatientStatus.New}>
                                            {Object.values(PatientStatus).map(s => <option key={s} value={s}>{s}</option>)}
                                        </select>
                                    </div>
                                </div>
                            </div>
                         </div>
                     </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 shrink-0">
                      <button 
                        type="button"
                        onClick={() => setIsAddingPatient(false)} 
                        className="px-6 py-2.5 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors"
                      >
                          Cancelar
                      </button>
                      <button 
                        onClick={(e) => {
                            // Trigger form submit programmatically or wrapping form
                            const form = e.currentTarget.closest('.bg-white')?.querySelector('form');
                            form?.requestSubmit();
                        }}
                        className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow-md transition-all flex items-center gap-2"
                      >
                          <CheckCircle size={18} />
                          Registrar Paciente
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Patient Registration Success Toast */}
      {patientSuccess && (
         <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[70] animate-in slide-in-from-bottom-5 fade-in duration-300">
             <div className="bg-emerald-600 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3">
                 <CheckCircle size={20} className="text-white" />
                 <span className="font-bold text-sm">{patientSuccess}</span>
             </div>
         </div>
      )}
    </div>
  );
};

export enum Discipline {
  Refractive = "Cirugía Refractiva",
  Cornea = "Transplante de Córnea",
  Pediatric = "Pediátrica",
  General = "Oftalmología General",
  LowVision = "Baja Visión",
  Oculoplasty = "Oculoplastia",
  Cataract = "Catarata",
  Neuro = "Neuroftalmología",
  DryEye = "Ojo Seco"
}

export enum PatientStatus {
  New = "Nuevo",
  InEvaluation = "En Evaluación",
  PreOp = "Pre-Operatorio",
  Scheduled = "Agendado",
  PostOp = "Post-Operatorio",
  Discharged = "De Alta"
}

export interface Diagnosis {
  date: string;
  code: string; // CIE-10
  description: string;
  eye: 'OD' | 'OI' | 'OU';
}

export interface PhysicalExamField {
  name: string;
  od: string;
  oi: string;
}

export interface MedicalRecord {
  id: string;
  date: string;
  time?: string;
  eventNumber?: string;
  type: 'Consulta' | 'Cirugía' | 'Seguimiento';
  title: string;
  doctor: string;

  // Clinical Data
  reason?: string; // Motivo consulta
  currentIllness?: string; // Enfermedad actual
  analysisPlan?: string; // Análisis y plan

  // Structured Exam
  physicalExam?: PhysicalExamField[];

  // Diagnoses
  diagnoses?: Diagnosis[];

  // Legacy notes field
  notes?: string; 
}

export interface LabResult {
  id: string;
  date: string;
  testName: string;
  result: string;
  referenceRange: string;
  status: 'Normal' | 'Abnormal' | 'Critical';
  fileUrl?: string;
}

export interface Examination {
  id: string;
  date: string;
  examType: string; // e.g., "Pentacam", "OCT", "Topography"
  summary: string;
  performedBy: string;
  imageUrl?: string;
}

export interface ProcedureLog {
  id: string;
  date: string;
  procedureName: string;
  doctor: string;
  outcome: string;
  notes: string;
}

export interface CommunicationLog {
  id: string;
  date: string;
  type: 'Call' | 'Email' | 'WhatsApp' | 'In-Person';
  notes: string;
  staffName: string;
}

// New Interface for AI Screening (Diabetic Retinopathy)
export interface AIScreening {
  id: string;
  date: string;
  modality: 'Retinografía' | 'OCT';
  riskLevel: 'No Referable' | 'Moderado' | 'Severo' | 'Proliferativo';
  confidenceScore: number; // 0-100
  aiFindings: string[]; // e.g., "Microaneurismas detectados", "Exudados duros"
  imageUrl: string;
  status: 'Pending' | 'Verified' | 'Rejected';
}

// New Interface for Dry Eye Assessment
export interface DryEyeAssessment {
  id: string;
  date: string;
  osdiScore: number; // Ocular Surface Disease Index (0-100)
  symptoms: string[];
  severity: 'Normal' | 'Leve' | 'Moderado' | 'Severo';
}

export interface AuditLogEntry {
  id: string;
  date: string;
  action: string;
  details: string;
  user: string;
}

export interface Patient {
  id: string;
  cedula?: string; 
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  dob: string;
  discipline: Discipline;
  status: PatientStatus;
  lastVisit: string;
  balance: number;
  avatarUrl: string;
  insuranceProvider?: string;
  policyNumber?: string;
  medicalHistory: MedicalRecord[];
  communicationLogs: CommunicationLog[];
  labResults: LabResult[];
  examinations: Examination[];
  procedures: ProcedureLog[];
  aiScreenings?: AIScreening[]; 
  dryEyeAssessments?: DryEyeAssessment[];
  auditLog: AuditLogEntry[]; // New field for tracking changes
  notes?: string;
}

export interface Appointment {
  id: string;
  patientId: string;
  patientName: string;
  date: string;
  time: string;
  reason: string;
  doctor: string;
  status: 'Scheduled' | 'Completed' | 'Cancelled';
  discipline: Discipline;
}

export interface Service {
  id: string;
  name: string;
  description: string;
  discipline: Discipline;
  durationMinutes: number;
  cost: number;
}

export interface Transaction {
  id: string;
  date: string;
  description: string;
  amount: number;
  type: 'income' | 'expense';
  category: string;
  discipline?: Discipline;
  patientId?: string; 
}

export interface KPI {
  label: string;
  value: string | number;
  change: number; 
  trend: 'up' | 'down' | 'neutral';
}

export type UserRole = 'admin' | 'doctor' | 'patient';

export type ViewState = 'dashboard' | 'crm' | 'appointments' | 'refractive-flow' | 'accounting' | 'services' | 'settings' | 'my-health' | 'education' | 'faq';

import React from 'react';
import { LayoutDashboard, Users, Activity, DollarSign, BookOpen, LogOut, Calendar, HeartPulse, FileText, HelpCircle, X } from 'lucide-react';
import { ViewState, UserRole } from '../types';
import { LOGO_URL } from '../constants';

interface SidebarProps {
  currentView: ViewState;
  onChangeView: (view: ViewState) => void;
  userRole: UserRole;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ currentView, onChangeView, userRole, onLogout, isOpen, onClose }) => {

  const allNavItems = [
    // Admin / Doctor Items
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: ['admin', 'doctor'] },
    { id: 'appointments', label: 'Citas', icon: Calendar, roles: ['admin', 'doctor'] },
    { id: 'crm', label: 'Pacientes (CRM)', icon: Users, roles: ['admin', 'doctor'] },
    { id: 'refractive-flow', label: 'Flujo Refractiva', icon: Activity, roles: ['admin', 'doctor'] },
    { id: 'accounting', label: 'Contabilidad', icon: DollarSign, roles: ['admin'] },

    // Patient Items
    { id: 'my-health', label: 'Mi Historial', icon: HeartPulse, roles: ['patient'] },
    { id: 'appointments', label: 'Mis Citas', icon: Calendar, roles: ['patient'] },

    // Shared - Moved here to appear after Appointments for Patient view
    { id: 'services', label: 'Catálogo Servicios', icon: BookOpen, roles: ['admin', 'doctor', 'patient'] },

    { id: 'education', label: 'Educación & Cuidados', icon: FileText, roles: ['patient'] },
    { id: 'faq', label: 'Preguntas Frecuentes', icon: HelpCircle, roles: ['patient'] },
  ];

  const visibleNavItems = allNavItems.filter(item => item.roles.includes(userRole));

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-20 md:hidden"
            onClick={onClose}
        />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white flex flex-col h-screen shadow-xl transition-transform duration-300 ease-in-out
        md:translate-x-0 md:static md:inset-auto
        ${isOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 flex items-center gap-3 border-b border-slate-800 justify-between">
          <div className="flex items-center gap-3 overflow-hidden">
            <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center p-1 overflow-hidden shrink-0">
                <img src={LOGO_URL} alt="Centro Laser Logo" className="object-contain w-full h-full" />
            </div>
            <div className="overflow-hidden">
              <h1 className="font-bold text-lg leading-tight truncate">Centro Laser</h1>
              <p className="text-xs text-slate-400">Sistema Integral</p>
            </div>
          </div>
          {/* Mobile Close Button */}
          <button onClick={onClose} className="md:hidden text-slate-400 hover:text-white">
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 px-3 py-6 space-y-1 overflow-y-auto">
          {visibleNavItems.map((item) => {
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => onChangeView(item.id as ViewState)}
                className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg transition-all duration-200 group ${
                  isActive 
                    ? 'bg-blue-700 text-white shadow-md' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <item.icon size={20} className={isActive ? 'text-white' : 'text-slate-400 group-hover:text-white'} />
                <span className="font-medium text-sm">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={onLogout}
            className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:text-red-400 transition-colors rounded-lg hover:bg-slate-800"
          >
            <LogOut size={18} />
            <span className="text-sm font-medium">Cerrar Sesión</span>
          </button>
        </div>
      </aside>
    </>
  );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { PatientManager } from './components/PatientManager';
import { RefractiveFlow } from './components/RefractiveFlow';
import { Accounting } from './components/Accounting';
import { ServiceCatalog } from './components/ServiceCatalog';
import { AuthScreen } from './components/AuthScreen';
import { Appointments } from './components/Appointments';
import { MyHealth } from './components/MyHealth';
import { PatientEducation } from './components/PatientEducation';
import { FAQ } from './components/FAQ';
import { ViewState, UserRole, Patient, Appointment } from './types';
import { MOCK_PATIENTS, MOCK_APPOINTMENTS, SERVICES } from './constants';
import { Bell, Search, MessageCircle, Menu, User, BookOpen } from 'lucide-react';

export default function App() {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>('doctor');
  const [currentPatientId, setCurrentPatientId] = useState<string>('P-1001'); // Mock logged-in patient

  // Data State (Lifted for persistence between views)
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [appointments, setAppointments] = useState<Appointment[]>(MOCK_APPOINTMENTS);

  // View State
  const [currentView, setCurrentView] = useState<ViewState>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Global Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);

  const handleLogin = (role: UserRole) => {
    setUserRole(role);
    setIsAuthenticated(true);
    // Redirect based on role
    if (role === 'patient') {
        setCurrentView('my-health');
        // In a real app, we'd fetch the patient ID from auth. 
        // For demo, we default to P-1001 (Rosa)
        setCurrentPatientId('P-1001'); 
    }
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUserRole('doctor'); 
    setCurrentView('dashboard');
    setIsSidebarOpen(false);
  };

  const handleAddAppointment = (newAppt: Appointment) => {
    setAppointments(prev => [...prev, newAppt]);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
  };

  const handleUpdatePatient = (updatedPatient: Patient) => {
    setPatients(prev => prev.map(p => p.id === updatedPatient.id ? updatedPatient : p));
  };

  // Global Search Logic
  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const query = e.target.value;
    setSearchQuery(query);

    if (query.length < 2) {
      setSearchResults([]);
      return;
    }

    const lowerQuery = query.toLowerCase();

    const matchedPatients = patients.filter(p => 
      p.firstName.toLowerCase().includes(lowerQuery) || 
      p.lastName.toLowerCase().includes(lowerQuery) ||
      p.id.toLowerCase().includes(lowerQuery)
    ).map(p => ({ ...p, type: 'patient' }));

    const matchedServices = SERVICES.filter(s => 
      s.name.toLowerCase().includes(lowerQuery)
    ).map(s => ({ ...s, type: 'service' }));

    setSearchResults([...matchedPatients, ...matchedServices]);
  };

  const handleSelectSearchResult = (result: any) => {
      setSearchQuery('');
      setSearchResults([]);
      if (result.type === 'patient') {
          setCurrentView('crm');
          // ideally we would also pass the selected patient ID to the CRM view to auto-open it
      } else if (result.type === 'service') {
          setCurrentView('services');
      }
  };

  // Get current patient data for MyHealth view
  const currentPatient = patients.find(p => p.id === currentPatientId) || patients[0];

  if (!isAuthenticated) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard />;
      case 'appointments':
        return <Appointments 
                  appointments={appointments} 
                  patients={patients} 
                  userRole={userRole} 
                  currentUserId={currentPatientId} 
               />;
      case 'crm':
        return <PatientManager 
                  patients={patients} 
                  appointments={appointments}
                  onAddAppointment={handleAddAppointment}
                  onAddPatient={handleAddPatient}
                  onUpdatePatient={handleUpdatePatient}
               />;
      case 'services':
        return <ServiceCatalog userRole={userRole} />;
      case 'refractive-flow':
        return <RefractiveFlow patients={patients} onAddPatient={handleAddPatient} />;
      case 'accounting':
        return <Accounting />;
      // Patient Portal Views
      case 'my-health':
        return <MyHealth patient={currentPatient} />;
      case 'education':
        return <PatientEducation />;
      case 'faq':
        return <FAQ />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-slate-50 font-sans">
      <Sidebar 
        currentView={currentView} 
        onChangeView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} 
        userRole={userRole}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 transition-all duration-300 relative">
        {/* Top Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-6 shadow-sm z-10 shrink-0">

          <div className="flex items-center gap-3">
             <button 
                className="md:hidden text-slate-500 hover:text-blue-600 p-1"
                onClick={() => setIsSidebarOpen(true)}
             >
                 <Menu size={24} />
             </button>

              {/* Global Search */}
              <div className="w-64 lg:w-96 relative hidden md:block">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder={userRole === 'patient' ? "Buscar en mi historial..." : "Búsqueda global..."}
                  className="w-full bg-slate-100 border-none rounded-lg pl-10 pr-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                  value={searchQuery}
                  onChange={handleSearch}
                />

                {/* Search Dropdown */}
                {searchResults.length > 0 && (
                    <div className="absolute top-full left-0 w-full bg-white rounded-lg shadow-xl border border-slate-200 mt-2 max-h-80 overflow-y-auto z-50">
                        {searchResults.map((result, idx) => (
                            <div 
                                key={idx} 
                                onClick={() => handleSelectSearchResult(result)}
                                className="p-3 hover:bg-slate-50 cursor-pointer border-b border-slate-100 last:border-0 flex items-center gap-3"
                            >
                                <div className={`p-2 rounded-full ${result.type === 'patient' ? 'bg-blue-100 text-blue-600' : 'bg-green-100 text-green-600'}`}>
                                    {result.type === 'patient' ? <User size={16} /> : <BookOpen size={16} />}
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-slate-900">{result.name || `${result.firstName} ${result.lastName}`}</p>
                                    <p className="text-xs text-slate-500">{result.type === 'patient' ? `ID: ${result.id}` : 'Servicio'}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
              </div>
          </div>

          <div className="flex items-center gap-3 md:gap-4">
             {/* Global WhatsApp Button */}
             <a 
                href="https://wa.me/" 
                target="_blank" 
                rel="noopener noreferrer"
                className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-3 py-1.5 rounded-full text-xs font-bold transition-colors shadow-sm"
             >
                <MessageCircle size={16} />
                <span className="hidden sm:inline">WhatsApp</span>
             </a>

            <button className="text-slate-400 hover:text-blue-600 transition-colors relative">
                <Bell size={20} />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full"></span>
            </button>
            <div className="w-px h-8 bg-slate-200 mx-1 md:mx-2"></div>
            <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity">
                <div className="text-right hidden sm:block">
                    <p className="text-sm font-bold text-slate-800">
                      {userRole === 'admin' ? 'Dr. Juan Batlle Logroño' : userRole === 'doctor' ? 'Dr. Especialista' : 'Rosa Martinez'}
                    </p>
                    <p className="text-xs text-slate-500 capitalize">{userRole}</p>
                </div>
                <div className={`w-8 h-8 md:w-9 md:h-9 rounded-full flex items-center justify-center font-bold border ${
                    userRole === 'admin' 
                    ? 'bg-blue-100 text-blue-700 border-blue-200' 
                    : userRole === 'doctor'
                    ? 'bg-emerald-100 text-emerald-700 border-emerald-200'
                    : 'bg-indigo-100 text-indigo-700 border-indigo-200'
                }`}>
                    <span className="text-xs md:text-sm">{userRole === 'admin' ? 'JB' : userRole === 'doctor' ? 'DE' : 'RM'}</span>
                </div>
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-auto p-4 md:p-6 scroll-smooth">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
}

