import React, { useState } from 'react';
import { REFRACTIVE_STEPS } from '../constants';
import { Patient, Discipline, PatientStatus } from '../types';
import { Eye, ChevronRight, MoreHorizontal, Clock, Plus, X, User, Phone, Mail, CheckCircle } from 'lucide-react';

interface RefractiveFlowProps {
  patients: Patient[];
  onAddPatient: (patient: Patient) => void;
}

export const RefractiveFlow: React.FC<RefractiveFlowProps> = ({ patients, onAddPatient }) => {
  const [isAddingCandidate, setIsAddingCandidate] = useState(false);

  // Filter only Refractive patients for this view
  const refractivePatients = patients.filter(p => p.discipline === Discipline.Refractive);

  // In a real app, 'status' would map to these steps. 
  // For this demo, we'll randomly assign them to columns if they don't match exactly.
  const getPatientsForStep = (stepId: string) => {
    // Determine pseudo-logic for distribution since our mock data has limited statuses
    // This simulates the organigram flow
    return refractivePatients.filter(p => {
        // Simple hashing for demo distribution
        const hash = p.id.charCodeAt(p.id.length - 1) % REFRACTIVE_STEPS.length;
        return REFRACTIVE_STEPS[hash].id === stepId;
    });
  };

  const handleSaveCandidate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const newPatient: Patient = {
        id: `P-${Math.floor(Math.random() * 10000)}`,
        firstName: formData.get('firstName') as string,
        lastName: formData.get('lastName') as string,
        email: formData.get('email') as string,
        phone: formData.get('phone') as string,
        cedula: '', // Can be added later
        dob: new Date().toISOString().split('T')[0], // Default to today or add field
        discipline: Discipline.Refractive,
        status: PatientStatus.New,
        lastVisit: new Date().toISOString().split('T')[0],
        balance: 0,
        avatarUrl: `https://ui-avatars.com/api/?name=${formData.get('firstName')}+${formData.get('lastName')}&background=0D8ABC&color=fff`,
        medicalHistory: [],
        communicationLogs: [],
        labResults: [],
        examinations: [],
        procedures: [],
        auditLog: [{
            id: `LOG-${Date.now()}`,
            date: new Date().toLocaleString(),
            action: 'Creación (Refractiva)',
            details: 'Candidato rápido registrado desde flujo refractivo.',
            user: 'Staff Actual'
        }]
    };

    onAddPatient(newPatient);
    setIsAddingCandidate(false);
  };

  return (
    <div className="h-full flex flex-col relative">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Flujo Cirugía Refractiva</h2>
          <p className="text-slate-500 text-sm mt-1">
            Seguimiento de pacientes basado en el organigrama clínico
          </p>
        </div>
        <button 
            onClick={() => setIsAddingCandidate(true)}
            className="bg-blue-900 hover:bg-blue-800 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-sm transition-colors flex items-center gap-2"
        >
          <Plus size={16} /> Nuevo Candidato
        </button>
      </div>

      {/* Kanban Board */}
      <div className="flex-1 overflow-x-auto pb-4">
        <div className="flex gap-4 min-w-max h-full">
          {REFRACTIVE_STEPS.map((step, index) => {
            const stepPatients = getPatientsForStep(step.id);

            return (
              <div key={step.id} className="w-80 flex flex-col h-full">
                {/* Column Header */}
                <div className="flex items-center gap-2 mb-3 bg-slate-200 rounded-t-lg p-3 border-b-4 border-blue-900">
                    <div className="flex items-center justify-center w-6 h-6 rounded-full bg-slate-900 text-white text-xs font-bold">
                        {index + 1}
                    </div>
                  <h3 className="font-semibold text-slate-700 text-sm uppercase tracking-wide">
                    {step.label}
                  </h3>
                  <span className="ml-auto bg-white px-2 py-0.5 rounded-full text-xs text-slate-500 font-bold">
                    {stepPatients.length}
                  </span>
                </div>

                {/* Drop Zone / List */}
                <div className="bg-slate-100 rounded-b-lg p-2 flex-1 overflow-y-auto space-y-3 min-h-[500px]">
                  {stepPatients.length === 0 ? (
                    <div className="h-24 flex items-center justify-center text-slate-400 text-xs italic border-2 border-dashed border-slate-300 rounded-lg">
                      Sin pacientes
                    </div>
                  ) : (
                    stepPatients.map(patient => (
                      <div 
                        key={patient.id} 
                        draggable 
                        className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:shadow-md cursor-grab active:cursor-grabbing transition-all group"
                      >
                        <div className="flex justify-between items-start mb-2">
                          <span className="text-xs font-mono text-slate-400">{patient.id}</span>
                          <button className="text-slate-300 hover:text-slate-600">
                            <MoreHorizontal size={16} />
                          </button>
                        </div>

                        <div className="flex items-center gap-3 mb-3">
                            <img src={patient.avatarUrl} alt="" className="w-10 h-10 rounded-full object-cover border border-slate-100" />
                            <div>
                                <h4 className="text-sm font-bold text-slate-800">{patient.firstName} {patient.lastName}</h4>
                                <span className="text-xs text-slate-500 block">{patient.phone}</span>
                            </div>
                        </div>

                        <div className="flex items-center justify-between pt-3 border-t border-slate-50">
                            <div className="flex items-center gap-1 text-xs text-orange-500 bg-orange-50 px-2 py-1 rounded">
                                <Clock size={12} />
                                <span>15 min</span>
                            </div>
                            <button className="text-blue-600 hover:bg-blue-50 p-1.5 rounded transition-colors">
                                <ChevronRight size={16} />
                            </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* New Candidate Modal */}
      {isAddingCandidate && (
          <div className="absolute inset-0 bg-slate-900/50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                      <div>
                        <h3 className="text-xl font-bold text-slate-900">Nuevo Candidato Refractivo</h3>
                        <p className="text-sm text-slate-500">Registro rápido para evaluación inicial</p>
                      </div>
                      <button onClick={() => setIsAddingCandidate(false)} className="text-slate-400 hover:text-red-500">
                        <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSaveCandidate} className="p-6 space-y-6">
                     <div className="space-y-4">
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="flex items-center gap-1 text-xs font-bold text-slate-500">
                                    <User size={14}/> Nombre
                                </label>
                                <input name="firstName" required type="text" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Nombre" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500">Apellido</label>
                                <input name="lastName" required type="text" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Apellido" />
                            </div>
                         </div>

                         <div className="space-y-1">
                            <label className="flex items-center gap-1 text-xs font-bold text-slate-500">
                                <Phone size={14}/> Teléfono
                            </label>
                            <input name="phone" required type="tel" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="(809) ..." />
                         </div>

                         <div className="space-y-1">
                            <label className="flex items-center gap-1 text-xs font-bold text-slate-500">
                                <Mail size={14}/> Email
                            </label>
                            <input name="email" required type="email" className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="correo@ejemplo.com" />
                         </div>
                     </div>

                     <div className="pt-2 flex justify-end gap-3">
                          <button 
                            type="button"
                            onClick={() => setIsAddingCandidate(false)} 
                            className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium"
                          >
                              Cancelar
                          </button>
                          <button 
                            type="submit"
                            className="px-6 py-2 bg-blue-900 hover:bg-blue-800 text-white rounded-lg text-sm font-bold shadow-md flex items-center gap-2"
                          >
                              <CheckCircle size={16} />
                              Registrar
                          </button>
                     </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

