import React, { useState } from 'react';
import { Appointment, Patient, UserRole } from '../types';
import { Clock, MessageCircle, AlertCircle, Calendar, User, Search, ExternalLink } from 'lucide-react';

interface AppointmentsProps {
  appointments: Appointment[];
  patients: Patient[];
  userRole: UserRole;
  currentUserId?: string;
}

export const Appointments: React.FC<AppointmentsProps> = ({ appointments, patients, userRole, currentUserId }) => {
  const [filterDate, setFilterDate] = useState<string>('');

  // Filter Logic: If Patient, only show their appointments.
  const relevantAppointments = userRole === 'patient' 
    ? appointments.filter(apt => apt.patientId === currentUserId)
    : appointments;

  const filteredAppointments = relevantAppointments.filter(apt => {
      if (!filterDate) return true;
      return apt.date === filterDate;
  }).sort((a, b) => new Date(`${a.date}T${a.time}`).getTime() - new Date(`${b.date}T${b.time}`).getTime());

  // Demo tomorrow date
  const demoTomorrowStr = '2024-06-10'; 
  const upcomingReminders = relevantAppointments.filter(apt => apt.date === demoTomorrowStr && apt.status === 'Scheduled');

  const getPatientPhone = (id: string) => {
      return patients.find(p => p.id === id)?.phone || '';
  };

  const sendReminder = (apt: Appointment) => {
    const phone = getPatientPhone(apt.patientId);
    if (!phone) {
        alert("No se encontró número de teléfono para este paciente.");
        return;
    }
    const cleanNumber = phone.replace(/\D/g, '');
    const fullNumber = cleanNumber.length === 10 ? `1${cleanNumber}` : cleanNumber;

    const message = `Hola ${apt.patientName}, le recordamos su cita en Centro Laser mañana ${apt.date} a las ${apt.time} con el ${apt.doctor}.`;
    window.open(`https://wa.me/${fullNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const addToGoogleCalendar = (apt: Appointment) => {
    // Format: YYYYMMDDTHHmmSS
    const startDateTime = new Date(`${apt.date}T${apt.time}`).toISOString().replace(/-|:|\.\d+/g, '');
    const endDateTime = new Date(new Date(`${apt.date}T${apt.time}`).getTime() + 60 * 60 * 1000).toISOString().replace(/-|:|\.\d+/g, ''); // Assume 1 hour

    const title = encodeURIComponent(`Cita Centro Laser: ${apt.reason}`);
    const details = encodeURIComponent(`Doctor: ${apt.doctor}\nPaciente: ${apt.patientName}\nMotivo: ${apt.reason}`);
    const location = encodeURIComponent("Centro Laser, Calle Fantino Falco #3, Naco, Santo Domingo");

    const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${startDateTime}/${endDateTime}&details=${details}&location=${location}`;
    window.open(url, '_blank');
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-900">
                {userRole === 'patient' ? 'Mis Citas' : 'Agenda Médica'}
            </h2>
            <p className="text-slate-500 text-sm">
                {userRole === 'patient' ? 'Próximas consultas y cirugías programadas.' : 'Gestión de consultas y cirugías del centro.'}
            </p>
        </div>
        <div className="flex items-center gap-3">
            <div className="relative">
                <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input 
                    type="date" 
                    className="border border-slate-300 rounded-lg pl-10 pr-3 py-2 text-sm text-slate-600 focus:ring-2 focus:ring-blue-500 outline-none"
                    value={filterDate}
                    onChange={(e) => setFilterDate(e.target.value)}
                />
            </div>
        </div>
      </div>

      {/* Automated Reminders Section (Only visible to staff) */}
      {userRole !== 'patient' && upcomingReminders.length > 0 && (
          <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 animate-in slide-in-from-top-2">
              <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2 text-amber-800 font-bold">
                      <AlertCircle size={20} />
                      <h3>Recordatorios Pendientes (Próximas 24h)</h3>
                  </div>
                  <span className="text-xs bg-amber-200 text-amber-900 px-2 py-1 rounded-full font-bold">
                      {upcomingReminders.length} Citas
                  </span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                  {upcomingReminders.map(apt => (
                      <div key={apt.id} className="bg-white p-3 rounded-lg border border-amber-100 shadow-sm flex justify-between items-center">
                          <div>
                              <p className="text-sm font-bold text-slate-800">{apt.patientName}</p>
                              <p className="text-xs text-slate-500">{apt.time} - {apt.doctor}</p>
                          </div>
                          <button 
                            onClick={() => sendReminder(apt)}
                            className="bg-green-500 hover:bg-green-600 text-white p-2 rounded-full transition-colors shadow-sm"
                            title="Enviar WhatsApp"
                          >
                              <MessageCircle size={16} />
                          </button>
                      </div>
                  ))}
              </div>
          </div>
      )}

      {/* Appointment List */}
      <div className="flex-1 overflow-auto bg-white rounded-xl shadow-sm border border-slate-200">
          <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 sticky top-0 z-10">
                  <tr>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Fecha & Hora</th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">
                          {userRole === 'patient' ? 'Doctor' : 'Paciente'}
                      </th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Especialidad</th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Motivo</th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Acciones</th>
                  </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                  {filteredAppointments.map(apt => (
                      <tr key={apt.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-4 whitespace-nowrap">
                              <div className="flex items-center gap-2 text-slate-900 font-bold">
                                  <Clock size={16} className="text-blue-500" />
                                  {apt.time}
                              </div>
                              <div className="text-xs text-slate-500 ml-6">{apt.date}</div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                              {userRole === 'patient' ? (
                                  <div className="text-sm font-medium text-slate-900">{apt.doctor}</div>
                              ) : (
                                  <div>
                                    <div className="text-sm font-medium text-slate-900">{apt.patientName}</div>
                                    <div className="text-xs text-slate-500 flex items-center gap-1">
                                        <User size={10} /> {apt.patientId}
                                    </div>
                                  </div>
                              )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                               <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-50 text-indigo-700 border border-indigo-100">
                                  {apt.discipline}
                               </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                              {apt.reason}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-right">
                              <div className="flex items-center justify-end gap-2">
                                  {userRole === 'patient' ? (
                                    <span className={`text-xs font-bold px-3 py-1 rounded-full ${apt.status === 'Scheduled' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'}`}>
                                        {apt.status === 'Scheduled' ? 'Confirmada' : apt.status}
                                    </span>
                                  ) : (
                                    <button 
                                        onClick={() => sendReminder(apt)}
                                        className="text-green-600 hover:bg-green-50 px-3 py-1.5 rounded-lg text-xs font-bold inline-flex items-center gap-1 transition-colors border border-green-200"
                                    >
                                        <MessageCircle size={14} /> Recordar
                                    </button>
                                  )}

                                  <button
                                    onClick={() => addToGoogleCalendar(apt)}
                                    className="text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-2 py-1.5 rounded-lg transition-colors"
                                    title="Añadir a Google Calendar"
                                  >
                                      <ExternalLink size={16} />
                                  </button>
                              </div>
                          </td>
                      </tr>
                  ))}
                  {filteredAppointments.length === 0 && (
                      <tr>
                          <td colSpan={5} className="p-12 text-center text-slate-400">
                              <div className="flex flex-col items-center gap-2">
                                  <Calendar size={32} className="opacity-20" />
                                  <p>No hay citas programadas.</p>
                              </div>
                          </td>
                      </tr>
                  )}
              </tbody>
          </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DryEyeAssessment } from '../types';
import { AlertCircle, CheckCircle, ChevronLeft, Save } from 'lucide-react';

interface OSDITestProps {
  onComplete: (assessment: DryEyeAssessment) => void;
  onCancel: () => void;
}

const QUESTIONS = [
  // Subscale A: Ocular Symptoms
  { id: 1, text: "¿Son sensibles sus ojos a la luz?" },
  { id: 2, text: "¿Siente arenilla en los ojos?" },
  { id: 3, text: "¿Le duelen los ojos o los siente adoloridos?" },
  { id: 4, text: "¿Tiene visión borrosa?" },
  { id: 5, text: "¿Tiene mala visión?" },
  // Subscale B: Visual Function
  { id: 6, text: "¿Tiene problemas para leer?" },
  { id: 7, text: "¿Tiene problemas para conducir de noche?" },
  { id: 8, text: "¿Tiene problemas para trabajar con la computadora o cajero automático?" },
  { id: 9, text: "¿Tiene problemas para ver televisión?" },
  // Subscale C: Environmental Triggers
  { id: 10, text: "¿Se sienten incómodos sus ojos con viento?" },
  { id: 11, text: "¿Se sienten incómodos sus ojos en lugares con baja humedad (muy secos)?" },
  { id: 12, text: "¿Se sienten incómodos sus ojos en áreas con aire acondicionado?" },
];

const OPTIONS = [
  { value: 4, label: "Todo el tiempo" },
  { value: 3, label: "La mayor parte del tiempo" },
  { value: 2, label: "La mitad del tiempo" },
  { value: 1, label: "Parte del tiempo" },
  { value: 0, label: "Ninguna parte del tiempo" },
];

export const OSDITest: React.FC<OSDITestProps> = ({ onComplete, onCancel }) => {
  const [answers, setAnswers] = useState<Record<number, number>>({});

  const handleOptionSelect = (questionId: number, value: number) => {
    setAnswers(prev => ({ ...prev, [questionId]: value }));
  };

  const calculateScore = () => {
    const questionsAnswered = Object.keys(answers).length;
    if (questionsAnswered === 0) return 0;

    const sumScores = Object.values(answers).reduce((acc: number, curr: number) => acc + curr, 0);
    // OSDI Formula: (Sum of scores x 25) / Number of questions answered
    const score = (sumScores * 25) / questionsAnswered;
    return Math.round(score * 10) / 10; // Round to 1 decimal
  };

  const getSeverity = (score: number) => {
    if (score <= 12) return 'Normal';
    if (score <= 22) return 'Leve';
    if (score <= 32) return 'Moderado';
    return 'Severo';
  };

  const handleSubmit = () => {
    const score = calculateScore();
    const severity = getSeverity(score);

    // Extract prominent symptoms (score >= 3)
    const symptoms = QUESTIONS
        .filter(q => (answers[q.id] || 0) >= 3)
        .map(q => q.text.replace('¿', '').replace('?', '').trim());

    const assessment: DryEyeAssessment = {
      id: `OSDI-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      osdiScore: score,
      severity: severity as any,
      symptoms: symptoms.length > 0 ? symptoms : ['Sin síntomas severos']
    };

    onComplete(assessment);
  };

  const completedCount = Object.keys(answers).length;
  const isComplete = completedCount === QUESTIONS.length;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden max-w-2xl mx-auto">
      <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
        <div>
           <h3 className="text-xl font-bold">Cuestionario OSDI</h3>
           <p className="text-blue-100 text-sm">Índice de Enfermedad de la Superficie Ocular</p>
        </div>
        <button onClick={onCancel} className="bg-blue-700 hover:bg-blue-800 p-2 rounded-lg text-white">
            <ChevronLeft size={24} />
        </button>
      </div>

      <div className="p-6">
        <div className="mb-6 bg-blue-50 border border-blue-100 p-4 rounded-lg flex gap-3 text-sm text-blue-800">
            <AlertCircle size={20} className="shrink-0" />
            <p>Por favor, responda las siguientes 12 preguntas sobre su experiencia durante la última semana.</p>
        </div>

        <div className="space-y-8">
            {QUESTIONS.map((q) => (
                <div key={q.id} className="border-b border-slate-100 pb-6 last:border-0">
                    <p className="font-medium text-slate-900 mb-3">{q.id}. {q.text}</p>
                    <div className="flex flex-wrap gap-2">
                        {OPTIONS.map((opt) => (
                            <button
                                key={opt.value}
                                onClick={() => handleOptionSelect(q.id, opt.value)}
                                className={`px-3 py-2 rounded-lg text-xs font-medium border transition-all ${
                                    answers[q.id] === opt.value 
                                    ? 'bg-blue-600 text-white border-blue-600 shadow-md transform scale-105' 
                                    : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                                }`}
                            >
                                {opt.label}
                            </button>
                        ))}
                    </div>
                </div>
            ))}
        </div>

        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center">
            <div className="text-sm text-slate-500">
                Completado: <span className="font-bold text-slate-900">{completedCount} / 12</span>
            </div>
            <button 
                onClick={handleSubmit}
                disabled={completedCount === 0}
                className="bg-green-600 hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-6 py-3 rounded-xl font-bold shadow-md flex items-center gap-2 transition-all"
            >
                <Save size={18} />
                Guardar Resultados
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DryEyeAssessment } from '../types';
import { AlertCircle, CheckCircle, ChevronLeft, Save, HelpCircle, Calculator } from 'lucide-react';

interface OSDITestProps {
  onComplete: (assessment: DryEyeAssessment) => void;
  onCancel: () => void;
}

// Structure based on the provided PDF
const SECTIONS = [
    {
        title: "¿Has experimentado alguna de las siguientes alteraciones durante la última semana?",
        questions: [
            { id: 1, text: "Sensibilidad a la luz" },
            { id: 2, text: "Sensación de arenilla en los ojos" },
            { id: 3, text: "Dolor de ojos" },
            { id: 4, text: "Visión borrosa" },
            { id: 5, text: "Mala visión" },
        ]
    },
    {
        title: "¿Has tenido problemas en los ojos que te han limitado o impedido realizar alguna de las siguientes acciones durante la última semana?",
        questions: [
            { id: 6, text: "Leer" },
            { id: 7, text: "Conducir de noche" },
            { id: 8, text: "Trabajar con un ordenador o cajero automático" },
            { id: 9, text: "Ver la televisión" },
        ]
    },
    {
        title: "¿Has sentido incomodidad en los ojos en alguna de las siguientes situaciones durante la última semana?",
        questions: [
            { id: 10, text: "Viento" },
            { id: 11, text: "Lugares con baja humedad (muy secos)" },
            { id: 12, text: "Zonas con aire acondicionado" },
        ]
    }
];

const OPTIONS = [
  { value: 4, label: "En todo momento", mobileLabel: "Siempre (4)" },
  { value: 3, label: "Casi en todo momento", mobileLabel: "Casi siempre (3)" },
  { value: 2, label: "El 50% del tiempo", mobileLabel: "Mitad tiempo (2)" },
  { value: 1, label: "Casi en ningún momento", mobileLabel: "A veces (1)" },
  { value: 0, label: "En ningún momento", mobileLabel: "Nunca (0)" },
];

export const OSDITest: React.FC<OSDITestProps> = ({ onComplete, onCancel }) => {
  // Store answers. null represents "N/A" (No Contesta/No Sé)
  const [answers, setAnswers] = useState<Record<number, number | null>>({});

  const handleOptionSelect = (questionId: number, value: number | null) => {
    setAnswers(prev => ({ ...prev, [questionId]: value }));
  };

  const calculateScore = () => {
    // Filter out questions that have a numeric answer (exclude null/N/A)
    const validAnswers = Object.values(answers).filter((val): val is number => val !== null);
    const questionsAnswered = validAnswers.length;

    if (questionsAnswered === 0) return 0;

    const sumScores = validAnswers.reduce((acc, curr) => acc + curr, 0);

    // OSDI Formula: (Sum of scores x 25) / Number of questions answered
    const score = (sumScores * 25) / questionsAnswered;
    return Math.round(score * 10) / 10; // Round to 1 decimal
  };

  const getSeverity = (score: number) => {
    // PDF ranges: 
    // Normal: 0-12 (Hasta 13 in PDF text likely typo, usually 0-12)
    // Mild/Mod: 13-22
    // Mod/Severe: 23-100
    if (score <= 12) return 'Normal';
    if (score <= 22) return 'Leve';
    if (score <= 32) return 'Moderado';
    return 'Severo';
  };

  const handleSubmit = () => {
    const score = calculateScore();
    const severity = getSeverity(score);

    // Flatten questions to find symptoms
    const allQuestions = SECTIONS.flatMap(s => s.questions);

    // Extract prominent symptoms (score >= 3)
    const symptoms = allQuestions
        .filter(q => (answers[q.id] || 0) >= 3)
        .map(q => q.text);

    const assessment: DryEyeAssessment = {
      id: `OSDI-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      osdiScore: score,
      severity: severity as any,
      symptoms: symptoms.length > 0 ? symptoms : ['Sin síntomas severos reportados']
    };

    onComplete(assessment);
  };

  const totalQuestions = 12;
  const answeredCount = Object.keys(answers).length;
  const isComplete = answeredCount === totalQuestions;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden max-w-4xl mx-auto flex flex-col h-full max-h-[80vh]">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-700 to-blue-600 p-4 md:p-6 text-white flex justify-between items-center shrink-0">
        <div>
           <div className="flex items-center gap-2">
                <Calculator className="text-blue-200" size={24} />
                <h3 className="text-xl font-bold">Test de OSDI</h3>
           </div>
           <p className="text-blue-100 text-sm mt-1">Evaluación del tipo y grado de ojo seco.</p>
        </div>
        <button 
            onClick={onCancel} 
            className="bg-white/10 hover:bg-white/20 p-2 rounded-lg text-white transition-colors"
        >
            <ChevronLeft size={24} />
        </button>
      </div>

      {/* Instructions */}
      <div className="bg-blue-50 p-4 border-b border-blue-100 flex gap-3 text-sm text-blue-900 shrink-0">
          <AlertCircle size={20} className="shrink-0 text-blue-600" />
          <p>
            Conteste las siguientes preguntas seleccionando la casilla que mejor defina la frecuencia de sus síntomas 
            <strong> durante la última semana</strong>. Si una pregunta no aplica a su caso, seleccione <strong>"N/C"</strong>.
          </p>
      </div>

      {/* Questionnaire Body */}
      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
        {SECTIONS.map((section, idx) => (
            <div key={idx} className="space-y-4">
                <h4 className="font-bold text-slate-800 text-sm md:text-base border-b border-slate-200 pb-2 mb-4 leading-relaxed">
                    {section.title}
                </h4>

                <div className="space-y-6">
                    {section.questions.map((q) => (
                        <div key={q.id} className="bg-white rounded-lg">
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-2">
                                <p className="font-medium text-slate-700 text-sm md:text-base">
                                    <span className="text-slate-400 font-bold mr-2">{q.id}.</span>
                                    {q.text}
                                </p>
                            </div>

                            {/* Options Grid */}
                            <div className="grid grid-cols-3 md:grid-cols-6 gap-2">
                                {OPTIONS.map((opt) => (
                                    <button
                                        key={opt.value}
                                        onClick={() => handleOptionSelect(q.id, opt.value)}
                                        className={`px-2 py-3 rounded-lg text-xs font-medium border transition-all flex flex-col items-center justify-center gap-1 h-full ${
                                            answers[q.id] === opt.value 
                                            ? 'bg-blue-600 text-white border-blue-600 shadow-md ring-2 ring-blue-200' 
                                            : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 hover:border-slate-300'
                                        }`}
                                    >
                                        <span className="md:hidden">{opt.mobileLabel}</span>
                                        <span className="hidden md:block text-center">{opt.label}</span>
                                        <span className="hidden md:block text-[10px] opacity-70">({opt.value})</span>
                                    </button>
                                ))}
                                {/* N/A Option */}
                                <button
                                    onClick={() => handleOptionSelect(q.id, null)}
                                    className={`px-2 py-3 rounded-lg text-xs font-bold border transition-all flex flex-col items-center justify-center h-full ${
                                        answers[q.id] === null 
                                        ? 'bg-slate-600 text-white border-slate-600 shadow-md' 
                                        : 'bg-slate-50 text-slate-400 border-slate-200 hover:bg-slate-100'
                                    }`}
                                >
                                    <span>N/C</span>
                                    <span className="text-[9px] font-normal opacity-80 text-center leading-tight mt-0.5">No sé / No aplica</span>
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        ))}
      </div>

      {/* Footer / Actions */}
      <div className="p-4 md:p-6 border-t border-slate-200 bg-slate-50 shrink-0 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-2 text-sm text-slate-500">
             <div className="w-32 h-2 bg-slate-200 rounded-full overflow-hidden">
                 <div 
                    className="h-full bg-blue-500 transition-all duration-500 ease-out"
                    style={{ width: `${(answeredCount / totalQuestions) * 100}%` }}
                 ></div>
             </div>
             <span>{answeredCount} de {totalQuestions} respondidas</span>
        </div>

        <button 
            onClick={handleSubmit}
            disabled={!isComplete}
            className={`
                w-full md:w-auto px-8 py-3 rounded-xl font-bold shadow-md flex items-center justify-center gap-2 transition-all
                ${isComplete 
                    ? 'bg-green-600 hover:bg-green-700 text-white transform hover:scale-105' 
                    : 'bg-slate-300 text-slate-500 cursor-not-allowed'
                }
            `}
        >
            <Save size={18} />
            Calcular Resultados
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Search, Filter, Plus, Phone, Mail, ArrowLeft, Calendar, MessageCircle, Upload, X, ChevronUp, ChevronDown, CheckCircle, FileText, Microscope, Clipboard, Activity, BrainCircuit, ScanEye, User, CreditCard, Stethoscope, AlertCircle, Clock, History, FileSpreadsheet, Eye } from 'lucide-react';
import { Patient, PatientStatus, Discipline, Appointment, CommunicationLog, MedicalRecord } from '../types';
import { DOCTORS } from '../constants';

// Component to render a Clinical History Record (Consultation)
const ConsultationCard: React.FC<{ record: MedicalRecord }> = ({ record }) => (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mb-6">
        {/* Header */}
        <div className="bg-slate-50 p-4 border-b border-slate-200 flex flex-wrap justify-between items-center gap-2">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-100 text-blue-700 rounded-lg">
                    <Stethoscope size={20} />
                </div>
                <div>
                    <h4 className="font-bold text-slate-900 text-sm">Evento N. {record.eventNumber || record.id}</h4>
                    <p className="text-xs text-slate-500">{record.date} {record.time ? `- ${record.time}` : ''}</p>
                </div>
            </div>
            <div className="text-right">
                <p className="text-sm font-bold text-slate-800">{record.doctor}</p>
                <p className="text-xs text-slate-500 uppercase">{record.type}</p>
            </div>
        </div>

        <div className="p-6 space-y-6">
            {/* Clinical Info */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <h5 className="text-xs font-bold text-slate-500 uppercase mb-1">Motivo Consulta</h5>
                    <p className="text-sm text-slate-800 font-medium">{record.reason || record.title}</p>
                </div>
                <div>
                    <h5 className="text-xs font-bold text-slate-500 uppercase mb-1">Enfermedad Actual</h5>
                    <p className="text-sm text-slate-800">{record.currentIllness || 'Ninguna'}</p>
                </div>
            </div>

            {/* Physical Exam Table */}
            {record.physicalExam && record.physicalExam.length > 0 && (
                <div>
                    <h5 className="text-xs font-bold text-blue-700 uppercase mb-3 bg-blue-50 inline-block px-2 py-1 rounded">Examen Físico</h5>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left border-collapse">
                            <thead>
                                <tr className="border-b border-slate-200 text-xs text-slate-500 uppercase">
                                    <th className="py-2 pr-4 font-bold">Estructura</th>
                                    <th className="py-2 px-4 font-bold text-blue-600">OD (Derecho)</th>
                                    <th className="py-2 pl-4 font-bold text-blue-600">OI (Izquierdo)</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {record.physicalExam.map((exam, idx) => (
                                    <tr key={idx}>
                                        <td className="py-2 pr-4 font-medium text-slate-700">{exam.name}</td>
                                        <td className="py-2 px-4 text-slate-600">{exam.od}</td>
                                        <td className="py-2 pl-4 text-slate-600">{exam.oi}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* Diagnoses Table */}
            {record.diagnoses && record.diagnoses.length > 0 && (
                <div>
                    <h5 className="text-xs font-bold text-blue-700 uppercase mb-3 bg-blue-50 inline-block px-2 py-1 rounded">Impresión Diagnóstica</h5>
                    <div className="overflow-x-auto rounded-lg border border-slate-100">
                        <table className="w-full text-sm text-left bg-slate-50/50">
                            <thead>
                                <tr className="text-xs text-slate-500 uppercase border-b border-slate-200">
                                    <th className="p-3">Fecha</th>
                                    <th className="p-3">CIE-10</th>
                                    <th className="p-3">Diagnóstico</th>
                                    <th className="p-3 text-right">Ojo</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 bg-white">
                                {record.diagnoses.map((dx, idx) => (
                                    <tr key={idx}>
                                        <td className="p-3 text-slate-500 font-mono text-xs">{dx.date}</td>
                                        <td className="p-3 font-bold text-slate-700">{dx.code}</td>
                                        <td className="p-3 text-slate-800">{dx.description}</td>
                                        <td className="p-3 text-right font-bold text-blue-600">{dx.eye}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* Analysis & Plan */}
            <div className="bg-yellow-50 border border-yellow-100 p-4 rounded-lg">
                <h5 className="text-xs font-bold text-yellow-800 uppercase mb-2">Análisis y Plan</h5>
                <p className="text-sm text-slate-800 leading-relaxed font-medium">
                    {record.analysisPlan || record.notes}
                </p>
            </div>
        </div>
    </div>
);

interface PatientManagerProps {
  patients: Patient[];
  appointments: Appointment[];
  onAddAppointment: (appointment: Appointment) => void;
  onAddPatient: (patient: Patient) => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
}

type SortKey = 'lastName' | 'lastInteraction' | 'balance';
type SortDirection = 'asc' | 'desc';

export const PatientManager: React.FC<PatientManagerProps> = ({ patients, appointments, onAddAppointment, onAddPatient, onUpdatePatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [isAddingPatient, setIsAddingPatient] = useState(false);
  const [showFilters, setShowFilters] = useState(false);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>(null);

  // New Patient Form State
  const [newPatientAvatar, setNewPatientAvatar] = useState<string>('');
  const [emailError, setEmailError] = useState('');
  const [cedulaError, setCedulaError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  // Feedback State
  const [patientSuccess, setPatientSuccess] = useState<string | null>(null);

  // Filter States
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterId, setFilterId] = useState<string>('');
  const [filterMinBalance, setFilterMinBalance] = useState<string>('');
  const [filterMaxBalance, setFilterMaxBalance] = useState<string>('');
  const [filterLastCommFrom, setFilterLastCommFrom] = useState<string>('');
  const [filterLastCommTo, setFilterLastCommTo] = useState<string>('');

  // New Appointment Modal State
  const [showApptModal, setShowApptModal] = useState(false);
  const [appointmentSuccess, setAppointmentSuccess] = useState<{show: boolean, details?: Appointment} | null>(null);

  // Tab State
  const [activeTab, setActiveTab] = useState<'info'|'history'|'dry_eye'|'comms'|'labs'|'exams'|'procedures'|'ai'|'audit'>('info');
  const [newCommNote, setNewCommNote] = useState('');
  const [newCommType, setNewCommType] = useState<CommunicationLog['type']>('Call');

  // Helper to get raw date string for logic
  const getLastCommunicationRaw = (p: Patient): string | null => {
      if (!p.communicationLogs || p.communicationLogs.length === 0) return null;
      const sorted = [...p.communicationLogs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      return sorted[0].date;
  };

  const getLastCommunicationDateDisplay = (p: Patient) => {
      const date = getLastCommunicationRaw(p);
      return date || 'N/A';
  };

  const getStatusColor = (status: PatientStatus) => {
      switch(status) {
          case PatientStatus.New: return 'bg-blue-100 text-blue-700 border-blue-200';
          case PatientStatus.InEvaluation: return 'bg-purple-100 text-purple-700 border-purple-200';
          case PatientStatus.PreOp: return 'bg-orange-100 text-orange-700 border-orange-200';
          case PatientStatus.Scheduled: return 'bg-green-100 text-green-700 border-green-200';
          case PatientStatus.PostOp: return 'bg-cyan-100 text-cyan-700 border-cyan-200';
          case PatientStatus.Discharged: return 'bg-slate-100 text-slate-600 border-slate-200';
          default: return 'bg-slate-100 text-slate-600 border-slate-200';
      }
  };

  // 1. Filtering Logic
  let processedPatients = patients.filter(p => {
    const term = searchTerm.toLowerCase();
    const cleanTerm = term.replace(/\D/g, ''); // For phone matching (digits only)
    const patientPhoneClean = p.phone.replace(/\D/g, '');

    // Search: Name, ID, Cedula, DOB, Status, Phone, Email
    const matchesSearch = 
        p.firstName.toLowerCase().includes(term) || 
        p.lastName.toLowerCase().includes(term) ||
        p.id.toLowerCase().includes(term) ||
        (p.cedula && p.cedula.includes(term)) || 
        p.dob.includes(term) || 
        p.status.toLowerCase().includes(term) ||
        p.phone.includes(term) ||
        (cleanTerm.length > 0 && patientPhoneClean.includes(cleanTerm)) || // Fuzzy phone match
        p.email.toLowerCase().includes(term);

    const matchesStatus = filterStatus === 'All' || p.status === filterStatus;
    const matchesId = filterId === '' || p.id.toLowerCase().includes(filterId.toLowerCase());
    const matchesMinBal = filterMinBalance === '' || p.balance >= Number(filterMinBalance);
    const matchesMaxBal = filterMaxBalance === '' || p.balance <= Number(filterMaxBalance);

    // Date Range Filter for Last Communication
    let matchesDateRange = true;
    if (filterLastCommFrom || filterLastCommTo) {
        const lastComm = getLastCommunicationRaw(p);
        if (!lastComm) {
            matchesDateRange = false; // If filtering by date and no comms, exclude
        } else {
            const commDate = new Date(lastComm).getTime();
            const fromDate = filterLastCommFrom ? new Date(filterLastCommFrom).getTime() : -Infinity;
            const toDate = filterLastCommTo ? new Date(filterLastCommTo).getTime() : Infinity;
            matchesDateRange = commDate >= fromDate && commDate <= toDate;
        }
    }

    return matchesSearch && matchesStatus && matchesId && matchesMinBal && matchesMaxBal && matchesDateRange;
  });

  // 2. Sorting Logic
  if (sortConfig !== null) {
      processedPatients.sort((a, b) => {
          let aValue: any = '';
          let bValue: any = '';

          if (sortConfig.key === 'lastName') {
              aValue = a.lastName.toLowerCase();
              bValue = b.lastName.toLowerCase();
          } else if (sortConfig.key === 'balance') {
              aValue = a.balance;
              bValue = b.balance;
          } else if (sortConfig.key === 'lastInteraction') {
              aValue = getLastCommunicationRaw(a) || '';
              bValue = getLastCommunicationRaw(b) || '';
          }

          if (aValue < bValue) {
              return sortConfig.direction === 'asc' ? -1 : 1;
          }
          if (aValue > bValue) {
              return sortConfig.direction === 'asc' ? 1 : -1;
          }
          return 0;
      });
  }

  const handleSort = (key: SortKey) => {
      let direction: SortDirection = 'asc';
      if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
      if (sortConfig?.key !== key) return <div className="w-4 h-4" />; // Placeholder
      return sortConfig.direction === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />;
  };

  const getWhatsAppLink = (phone: string) => {
      const cleanNumber = phone.replace(/\D/g, '');
      const fullNumber = cleanNumber.length === 10 ? `1${cleanNumber}` : cleanNumber;
      return `https://wa.me/${fullNumber}`;
  };

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(
        /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|.(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
      );
  };

  const validateCedula = (cedula: string) => {
      // Basic Dominican Cedula format: 000-0000000-0
      return /^\d{3}-\d{7}-\d{1}$/.test(cedula);
  };

  const sendPushNotification = (doctorName: string, patientName: string, date: string, time: string) => {
    if (!("Notification" in window)) return;
    if (Notification.permission === "granted") {
      new Notification(`Nueva Cita: ${doctorName}`, {
        body: `Paciente: ${patientName}\nFecha: ${date} a las ${time}`,
        icon: 'https://i.imgur.com/DE2gOJW.jpeg'
      });
    } else if (Notification.permission !== "denied") {
      Notification.requestPermission().then((permission) => {
        if (permission === "granted") {
            new Notification(`Nueva Cita: ${doctorName}`, {
                body: `Paciente: ${patientName}\nFecha: ${date} a las ${time}`,
                icon: 'https://i.imgur.com/DE2gOJW.jpeg'
              });
        }
      });
    }
  };

  const handleSaveNewPatient = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const email = formData.get('email') as string;
    const cedula = formData.get('cedula') as string;

    if (!validateEmail(email)) {
        setEmailError('Por favor ingrese un correo electrónico válido.');
        return;
    }
    setEmailError('');

    if (cedula && !validateCedula(cedula)) {
        setCedulaError('Formato inválido. Use XXX-XXXXXXX-X');
        return;
    }
    setCedulaError('');

    const newPatient: Patient = {
        id: `P-${Math.floor(Math.random() * 10000)}`,
        firstName: formData.get('firstName') as string,
        lastName: formData.get('lastName') as string,
        email: email,
        phone: formData.get('phone') as string,
        cedula: cedula,
        dob: formData.get('dob') as string,
        discipline: formData.get('discipline') as Discipline,
        status: formData.get('status') as PatientStatus,
        lastVisit: new Date().toISOString().split('T')[0],
        balance: 0,
        avatarUrl: newPatientAvatar,
        medicalHistory: [],
        communicationLogs: [],
        labResults: [],
        examinations: [],
        procedures: [],
        auditLog: [{
            id: `LOG-${Date.now()}`,
            date: new Date().toLocaleString(),
            action: 'Creación',
            details: 'Paciente registrado en el sistema.',
            user: 'Staff Actual'
        }]
    };

    onAddPatient(newPatient);
    setIsAddingPatient(false);
    setPatientSuccess(`Paciente ${newPatient.firstName} ${newPatient.lastName} registrado correctamente.`);
    setTimeout(() => setPatientSuccess(null), 4000);
  };

  const handleCSVImport = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          // In a real app, parse the CSV here.
          // For now, we simulate success.
          setPatientSuccess("Pacientes importados correctamente desde CSV (Simulación).");
          setTimeout(() => setPatientSuccess(null), 4000);
          event.target.value = ''; // Reset input
      }
  };

  const handleUpdateStatus = (newStatus: PatientStatus) => {
      if(selectedPatient) {
          const updated = { 
              ...selectedPatient, 
              status: newStatus,
              auditLog: [
                  {
                      id: `LOG-${Date.now()}`,
                      date: new Date().toLocaleString(),
                      action: 'Cambio de Estado',
                      details: `Estado cambiado de ${selectedPatient.status} a ${newStatus}`,
                      user: 'Staff Actual'
                  },
                  ...(selectedPatient.auditLog || [])
              ]
           };
          onUpdatePatient(updated);
          setSelectedPatient(updated);
          setPatientSuccess("Paciente actualizado correctamente.");
          setTimeout(() => setPatientSuccess(null), 3000);
      }
  };

  const handleAddAppointment = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (!selectedPatient) return;

    const newAppt: Appointment = {
      id: `APT-${Date.now()}`,
      patientId: selectedPatient.id,
      patientName: `${selectedPatient.firstName} ${selectedPatient.lastName}`,
      date: formData.get('date') as string,
      time: formData.get('time') as string,
      reason: formData.get('reason') as string,
      doctor: formData.get('doctor') as string,
      status: 'Scheduled',
      discipline: selectedPatient.discipline
    };
    onAddAppointment(newAppt);
    setShowApptModal(false);

    // Notify Staff
    sendPushNotification(newAppt.doctor, newAppt.patientName, newAppt.date, newAppt.time);

    // Simulate Notification to Patient (Console/Alert in this demo context)
    // In a real app, this would trigger an email or SMS via backend
    console.log(`[SIMULACIÓN] Notificación enviada a paciente ${selectedPatient.email}: Su cita ha sido confirmada.`);

    setAppointmentSuccess({ show: true, details: newAppt });
    setTimeout(() => {
        setAppointmentSuccess(null);
    }, 6000);
  };

  const handleAddCommLog = () => {
    if (!selectedPatient || !newCommNote) return;
    const newLog: CommunicationLog = {
      id: `CL-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      type: newCommType,
      notes: newCommNote,
      staffName: 'Staff Actual' 
    };
    const updatedPatient = {
      ...selectedPatient,
      communicationLogs: [newLog, ...(selectedPatient.communicationLogs || [])]
    };
    onUpdatePatient(updatedPatient);
    setSelectedPatient(updatedPatient);
    setNewCommNote('');
  };

  const handleAvatarUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (e) => {
              if (e.target?.result) {
                  setNewPatientAvatar(e.target.result as string);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  if (selectedPatient) {
    return (
      <div className="h-full flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
        {/* Detail View Header */}
        <div className="p-4 md:p-6 border-b border-slate-100 bg-slate-50 flex flex-col md:flex-row items-start md:items-center gap-4">
          <button 
            onClick={() => setSelectedPatient(null)}
            className="p-2 hover:bg-white rounded-full transition-colors border border-transparent hover:border-slate-200 shadow-sm"
          >
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div className="flex items-center gap-4 flex-1 w-full">
            <img 
                src={selectedPatient.avatarUrl || 'https://via.placeholder.com/150'} 
                alt="Profile" 
                className="w-12 h-12 md:w-16 md:h-16 rounded-full border-4 border-white shadow-sm object-cover bg-slate-200" 
            />
            <div className="min-w-0 flex-1">
              <h2 className="text-lg md:text-2xl font-bold text-slate-900 truncate">{selectedPatient.firstName} {selectedPatient.lastName}</h2>
              <div className="flex flex-wrap items-center gap-2 md:gap-3 text-sm text-slate-500 mt-1">
                <span>{selectedPatient.id}</span>
                {selectedPatient.cedula && (
                    <span className="bg-slate-100 px-2 py-0.5 rounded text-xs font-mono hidden sm:inline-block">{selectedPatient.cedula}</span>
                )}
                <span className="text-blue-600 font-medium px-2 py-0.5 bg-blue-50 rounded-full text-xs truncate max-w-[150px]">{selectedPatient.discipline}</span>

                {/* Editable Status in Header */}
                <select 
                    value={selectedPatient.status}
                    onChange={(e) => handleUpdateStatus(e.target.value as PatientStatus)}
                    className={`text-xs font-bold px-2 py-1 rounded border-none focus:ring-2 focus:ring-blue-500 outline-none cursor-pointer ${
                         selectedPatient.status === PatientStatus.Scheduled ? 'bg-green-100 text-green-700' :
                         selectedPatient.status === PatientStatus.PreOp ? 'bg-orange-100 text-orange-700' :
                         selectedPatient.status === PatientStatus.PostOp ? 'bg-cyan-100 text-cyan-700' :
                         selectedPatient.status === PatientStatus.InEvaluation ? 'bg-purple-100 text-purple-700' :
                         'bg-slate-100 text-slate-700'
                    }`}
                >
                    {Object.values(PatientStatus).map(s => (
                        <option key={s} value={s}>{s}</option>
                    ))}
                </select>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3 w-full md:w-auto mt-2 md:mt-0 justify-between md:justify-end">
            <button 
                onClick={() => setShowApptModal(true)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm flex-1 md:flex-initial justify-center"
            >
                <Calendar size={16} /> <span className="hidden sm:inline">Agendar Cita</span><span className="sm:hidden">Agendar</span>
            </button>
            <div className="text-right px-4 py-2 bg-white rounded-lg border border-slate-200">
                <div className="text-xs text-slate-500 uppercase font-bold">Balance</div>
                <div className={`text-lg font-bold ${selectedPatient.balance > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                    RD$ {selectedPatient.balance.toLocaleString()}
                </div>
            </div>
          </div>
        </div>

        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
            <div className="hidden md:block w-80 border-r border-slate-100 p-6 overflow-y-auto space-y-6 bg-white">
                 <div>
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3">Contacto Rápido</h3>
                    <div className="space-y-3">
                        <div className="flex items-center gap-3 text-slate-700 p-2 bg-slate-50 rounded-lg">
                            <Phone size={18} />
                            <span className="font-mono text-sm">{selectedPatient.phone}</span>
                            <a 
                                href={getWhatsAppLink(selectedPatient.phone)} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="ml-auto bg-green-500 hover:bg-green-600 text-white px-[6px] py-[3px] rounded-md shadow-sm transition-colors border border-green-600 flex items-center gap-1"
                                title="Abrir WhatsApp"
                            >
                                <MessageCircle size={14} />
                            </a>
                        </div>
                        <div className="flex items-center gap-3 text-slate-700 p-2 bg-slate-50 rounded-lg">
                            <Mail size={18} />
                            <span className="text-sm truncate">{selectedPatient.email}</span>
                        </div>
                    </div>
                </div>
                 <div>
                    <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3">Seguro Médico</h3>
                    <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                        <p className="font-bold text-blue-900 text-sm">{selectedPatient.insuranceProvider || 'Privado'}</p>
                        <p className="font-mono text-slate-600 text-xs mt-1">{selectedPatient.policyNumber || 'N/A'}</p>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col bg-slate-50">
                <div className="flex border-b border-slate-200 bg-white px-6 overflow-x-auto">
                    {[
                        { id: 'info', label: 'Información General', icon: null },
                        { id: 'history', label: 'Historial Clínico', icon: FileText },
                        { id: 'dry_eye', label: 'Superficie Ocular', icon: Eye },
                        { id: 'ai', label: 'IA Screening', icon: BrainCircuit },
                        { id: 'labs', label: 'Laboratorios', icon: Microscope },
                        { id: 'exams', label: 'Exámenes', icon: Clipboard },
                        { id: 'procedures', label: 'Procedimientos', icon: Activity },
                        { id: 'comms', label: 'Bitácora', icon: MessageCircle },
                        { id: 'audit', label: 'Audit Log', icon: History }
                    ].map((tab) => (
                        <button 
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id as any)}
                            className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${
                                activeTab === tab.id 
                                ? 'border-blue-600 text-blue-600' 
                                : 'border-transparent text-slate-500 hover:text-slate-700'
                            }`}
                        >
                            {tab.icon && <tab.icon size={16} />}
                            {tab.label}
                        </button>
                    ))}
