import { jsPDF } from 'jspdf';
import { Patient, DryEyeAssessment } from './types';

export const generateOSDIPDF = (assessment: DryEyeAssessment, patient: Patient) => {
    const doc = new jsPDF();

    // Header Background
    doc.setFillColor(30, 64, 175); // Blue 800
    doc.rect(0, 0, 210, 24, 'F');

    // Header Text
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    doc.text("Centro Laser - Reporte Clínico", 15, 16);

    // Document Title
    doc.setTextColor(30, 30, 30);
    doc.setFontSize(22);
    doc.text("Resultados Test OSDI", 15, 45);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.setFont("helvetica", "normal");
    doc.text("Índice de Enfermedad de la Superficie Ocular", 15, 51);

    // Divider
    doc.setDrawColor(200);
    doc.line(15, 60, 195, 60);

    // Patient Details
    doc.setFontSize(11);
    doc.setTextColor(80);
    doc.text(`Paciente:`, 15, 75);
    doc.text(`ID:`, 15, 82);
    doc.text(`Fecha:`, 120, 75);

    doc.setFontSize(11);
    doc.setTextColor(0);
    doc.setFont("helvetica", "bold");
    doc.text(`${patient.firstName} ${patient.lastName}`, 40, 75);
    doc.text(`${patient.id}`, 40, 82);
    doc.text(`${assessment.date}`, 140, 75);

    // Results Box
    doc.setFillColor(240, 248, 255); // Light Blue
    doc.setDrawColor(200, 220, 255);
    doc.roundedRect(15, 95, 180, 55, 3, 3, 'FD');

    doc.setFont("helvetica", "normal");
    doc.setFontSize(14);
    doc.setTextColor(30, 58, 138); // Blue 900
    doc.text("Puntuación OSDI", 25, 110);

    doc.setFontSize(40);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(37, 99, 235); // Blue 600
    doc.text(assessment.osdiScore.toString(), 25, 132);

    doc.setFontSize(14);
    doc.setTextColor(50);
    doc.setFont("helvetica", "normal");
    doc.text("Diagnóstico:", 90, 110);

    doc.setFontSize(20);
    doc.setFont("helvetica", "bold");

    let severityColor = [30, 30, 30]; 
    if (assessment.severity === 'Normal') severityColor = [22, 163, 74]; 
    else if (assessment.severity === 'Leve') severityColor = [202, 138, 4];
    else if (assessment.severity === 'Moderado') severityColor = [234, 88, 12];
    else severityColor = [220, 38, 38];

    doc.setTextColor(severityColor[0], severityColor[1], severityColor[2]);
    doc.text(assessment.severity.toUpperCase(), 90, 125);

    // Reference Scale
    doc.setFontSize(9);
    doc.setTextColor(120);
    doc.setFont("helvetica", "normal");
    doc.text("0-12 Normal  |  13-22 Leve  |  23-32 Moderado  |  33-100 Severo", 25, 142);

    // Symptoms List
    doc.setFontSize(12);
    doc.setTextColor(0);
    doc.setFont("helvetica", "bold");
    doc.text("Síntomas Reportados:", 15, 170);

    doc.setFontSize(11);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(40);

    let yPos = 180;
    if (assessment.symptoms.length > 0) {
        assessment.symptoms.forEach((sym) => {
            doc.setFillColor(60);
            doc.circle(20, yPos - 1.5, 1.5, 'F');
            doc.text(sym, 26, yPos);
            yPos += 8;
        });
    } else {
        doc.text("No se reportaron síntomas significativos.", 20, yPos);
    }

    // Disclaimer
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text("Este documento es un reporte generado automáticamente. No sustituye el criterio médico profesional.", 15, 280);
    doc.text("Centro Laser © 2024", 15, 285);

    doc.save(`OSDI_${patient.firstName}_${assessment.date}.pdf`);
};

